insert into items (id, nivel, tipo, grupo, orden_grupo, instruccion_ja, enunciado, objetivo, opciones, respuesta, logica_distractores, explicacion, puntos, pasaje, guion, audio, etiquetas, dificultad) values
  ('n1-bunpou1-0001', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '事故の原因については、調査の結果を待つ（　）。', null, '["ほかない", "ものがある", "きらいがある", "にすぎない"]'::jsonb, 0, '["ものがあるは感嘆", "きらいがあるは傾向", "にすぎないは限定"]'::jsonb, '{"es": "〜ほかない = no queda más remedio. Es la única opción disponible.", "en": "〜ほかない = there''s nothing for it but. It''s the only option left."}'::jsonb, null, null, null, null, '["限定"]'::jsonb, 4),
  ('n1-bunpou1-0002', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '社長（　）者が、社員の前でそんな発言をするべきではない。', null, '["めく", "たる", "がち", "なる"]'::jsonb, 1, '["めくは様子", "がちは傾向", "なるは連体"]'::jsonb, '{"es": "〜たる者 = «quien es …, en su condición de». Marca la responsabilidad del cargo.", "en": "〜たる者 = ''one who is …, in that capacity''. It marks the duty of the role."}'::jsonb, null, null, null, null, '["立場"]'::jsonb, 5),
  ('n1-bunpou1-0003', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '雨天（　）、大会は予定どおり行われます。', null, '["にもまして", "をおいて", "といえども", "ならでは"]'::jsonb, 2, '["にもましては比較", "をおいてはただ一つ", "ならではは固有性"]'::jsonb, '{"es": "〜といえども = «aun siendo…, aunque sea…». Concesivo formal.", "en": "〜といえども = ''even if it is…''. A formal concessive."}'::jsonb, null, null, null, null, '["逆接"]'::jsonb, 5),
  ('n1-bunpou1-0004', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '皆様のご協力（　）、この計画は実現しませんでした。', null, '["をもって", "にかけては", "ながらに", "なくしては"]'::jsonb, 3, '["をもっては手段", "にかけてはは得意分野", "ながらには継続"]'::jsonb, '{"es": "〜なくしては = «sin …, no». Marca condición indispensable.", "en": "〜なくしては = ''without …, not''. It marks an indispensable condition."}'::jsonb, null, null, null, null, '["条件"]'::jsonb, 5),
  ('n1-bunpou1-0005', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この問題の難しさは、経験した者（　）分からないだろう。', null, '["でなければ", "であれば", "にしては", "とあって"]'::jsonb, 0, '["肯定条件では意味が逆", "にしてはは予想との差", "とあっては理由"]'::jsonb, '{"es": "者でなければ分からない = solo quien lo ha vivido lo entiende. La negativa es la que da el sentido.", "en": "者でなければ分からない = only someone who has lived it understands. The negative carries the meaning."}'::jsonb, null, null, null, null, '["限定"]'::jsonb, 4),
  ('n1-bunpou1-0006', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は忙しさ（　）、返事を出すのを忘れていたらしい。', null, '["をよそに", "にかまけて", "にひきかえ", "にもまして"]'::jsonb, 1, '["をよそには無視", "にひきかえは対比", "にもましては比較"]'::jsonb, '{"es": "〜にかまけて = estar tan absorbido por algo que se descuida lo demás.", "en": "〜にかまけて = to be so taken up with something that everything else is neglected."}'::jsonb, null, null, null, null, '["原因"]'::jsonb, 5),
  ('n1-bunpou2-0001', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', '今回の結果は　＿＿　＿★＿　＿＿　＿＿　ものだ。', null, '["努力の", "たまものと", "日ごろの", "言うべき"]'::jsonb, 0, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 日ごろの 努力の たまものと 言うべき. La estrella está en la casilla 2, donde va 「努力の」.", "en": "Order: 日ごろの 努力の たまものと 言うべき. The star is in slot 2, which takes 「努力の」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou2-0002', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'この装置は　＿＿　＿＿　＿★＿　＿＿　設計されている。', null, '["子どもでも", "安全に", "操作を誤っても", "使えるように"]'::jsonb, 1, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 子どもでも 操作を誤っても 安全に 使えるように. La estrella está en la casilla 3, donde va 「安全に」.", "en": "Order: 子どもでも 操作を誤っても 安全に 使えるように. The star is in slot 3, which takes 「安全に」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou1-0007', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この結果は、長年の地道な努力（　）ものだ。', null, '["ながらの", "ならではの", "あっての", "かぎりの"]'::jsonb, 2, '["ながらは継続", "ならではは固有性", "かぎりは限定"]'::jsonb, '{"es": "〜あっての = «que solo existe gracias a». Sin ese esfuerzo no habría resultado.", "en": "〜あっての = ''which exists only thanks to''. Without that effort there''d be no result."}'::jsonb, null, null, null, null, '["前提"]'::jsonb, 5),
  ('n1-bunpou1-0008', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '周囲の反対（　）、彼は計画を進めた。', null, '["にかかわって", "をこめて", "にそくして", "をよそに"]'::jsonb, 3, '["にかかわっては関与", "をこめては感情", "にそくしては基づく"]'::jsonb, '{"es": "〜をよそに = haciendo caso omiso de. Sigue adelante pese a la oposición.", "en": "〜をよそに = disregarding. He pressed on despite the opposition."}'::jsonb, null, null, null, null, '["無視"]'::jsonb, 5),
  ('n1-bunpou1-0009', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '締め切りが明日（　）、今から間に合わせるのは難しい。', null, '["とあっては", "とばかりに", "といっては", "ときたら"]'::jsonb, 0, '["とばかりには様子", "といってはは引用", "ときたらは話題提示"]'::jsonb, '{"es": "〜とあっては = «siendo el caso que…, entonces». Introduce una consecuencia forzosa.", "en": "〜とあっては = ''given that…, then''. It introduces an unavoidable consequence."}'::jsonb, null, null, null, null, '["条件"]'::jsonb, 5),
  ('n1-bunpou1-0010', 'N1', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の実力なら、優勝も（　）。', null, '["夢にすぎない", "夢ではあるまい", "夢どころではない", "夢ではあるまいし"]'::jsonb, 1, '["にすぎないは限定", "どころではないは余裕がない", "ではあるまいしは理由の否定"]'::jsonb, '{"es": "〜まい niega con conjetura: «no será un sueño», o sea, es alcanzable.", "en": "〜まい negates with conjecture: ''it likely isn''t a dream'', i.e. it''s within reach."}'::jsonb, null, null, null, null, '["推量"]'::jsonb, 5),
  ('n1-bunpou2-0003', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'その決断は　＿＿　＿★＿　＿＿　＿＿　ではない。', null, '["容易に", "下せるもの", "立場でなければ", "責任ある"]'::jsonb, 2, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 責任ある 立場でなければ 容易に 下せるもの. La estrella está en la casilla 2, donde va 「立場でなければ」.", "en": "Order: 責任ある 立場でなければ 容易に 下せるもの. The star is in slot 2, which takes 「立場でなければ」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunpou2-0004', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', '制度の見直しは　＿＿　＿＿　＿★＿　＿＿　進められた。', null, '["押し切る形で", "現場の声を", "踏まえつつ", "反対を"]'::jsonb, 3, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: 現場の声を 踏まえつつ 反対を 押し切る形で. La estrella está en la casilla 3, donde va 「反対を」.", "en": "Order: 現場の声を 踏まえつつ 反対を 押し切る形で. The star is in slot 3, which takes 「反対を」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 5),
  ('n1-bunshou_bunpou-0001', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 0, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　1　）', null, '["わかりやすさはかえって妨げになりうる", "わかりやすさこそが唯一の方法である", "聞き手の枠組みは問題にならない", "話し手の負担は軽くなる"]'::jsonb, 0, '["本文の論旨と逆", "枠組みが問題だと述べている", "負担の話は次の段落"]'::jsonb, '{"es": "Si hay que cambiar el marco del oyente, encajar la información en ese mismo marco estorba.", "en": "If the listener''s framework itself must change, fitting information into that framework gets in the way."}'::jsonb, null, '{"texto": "「わかりやすく話してください」と頼まれることがある。ありがたい要望だが、応じるのは思うほど簡単ではない。わかりやすさとは、聞き手がすでに持っている枠組みに情報を収めることだからだ。枠組みそのものを変えてもらう必要がある場合、（　1　）。\nそれでも、話し手にできることはある。結論を先に置くこと、例を一つに絞ること、専門語を言い換えること。これらはいずれも、聞き手の負担を減らす工夫である。（　2　）、内容そのものを薄めることとは違う。\n難しい話をやさしく話すのと、やさしい話に置き換えてしまうのとは別である。前者は聞き手への敬意だが、後者は（　3　）。両者の境目を見失わないことが、話し手の責任なのだと思う。", "notas": [{"termino": "枠組み", "glosa": "ものごとを理解するときの下地となる考え方"}]}'::jsonb, null, null, '["文章の文法"]'::jsonb, 5),
  ('n1-bunshou_bunpou-0002', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 1, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　2　）', null, '["たとえば", "ただし", "つまり", "したがって"]'::jsonb, 1, '["例示ではない", "言い換えではない", "帰結ではない"]'::jsonb, '{"es": "Va a poner un límite a lo dicho: reducir la carga sí, diluir el contenido no. ただし.", "en": "He''s about to qualify what he said: lighten the load yes, dilute the content no. ただし."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 4),
  ('n1-bunshou_bunpou-0003', 'N1', 'bunshou_bunpou', 'n1-bb-g001', 2, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　3　）', null, '["聞き手への配慮そのものである", "話し手の実力を示している", "聞き手を見くびることになりかねない", "内容を深めることにつながる"]'::jsonb, 2, '["前者の説明", "本文にない", "本文と逆"]'::jsonb, '{"es": "El primero es respeto; el segundo, sustituir el tema por otro más fácil, subestima al oyente.", "en": "The first is respect; the second — swapping the topic for an easier one — sells the listener short."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n1-bunpou2-0005', 'N1', 'bunpou2', null, 0, '次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。', '彼の努力　＿＿　＿＿　＿★＿　＿＿　だろう。', null, '["成功は", "なくして", "あり得なかった", "今日の"]'::jsonb, 0, '["語順が合わない", "語順が合わない", "語順が合わない"]'::jsonb, '{"es": "Orden: なくして 今日の 成功は あり得なかった. La estrella cae en la casilla 3, que lleva 「成功は」.", "en": "Order: なくして 今日の 成功は あり得なかった. The star is in slot 3, which takes 「成功は」."}'::jsonb, null, null, null, null, '["並べ替え"]'::jsonb, 6),
  ('n1-bunshou_bunpou-0004', 'N1', 'bunshou_bunpou', 'n1-bb-g002', 0, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　1　）', null, '["きわめて有益なものになる", "受け入れやすいものになる", "専門性の証明になる", "区別のつかないものになる"]'::jsonb, 3, '["本文は線を引かない助言を問題視している", "受け入れやすさは論点ではない", "線引きこそが専門性だと述べている"]'::jsonb, '{"es": "Sin la línea, quien escucha no puede separar lo sabido de lo supuesto: todo le llega igual.", "en": "Without the line, the listener can''t separate the known from the guessed: it all arrives the same."}'::jsonb, null, '{"texto": "専門家に求められるのは正解だと、長く信じられてきた。だが実務の場で本当に必要とされるのは、どこまでが分かっていて、どこからが分かっていないのかを線引きする力である。前者だけを示せば頼もしく見えるが、線を引かない助言は、受け取る側から見れば（　1　）。\n断定は安心を与える。だからこそ、断定できない領域を断定してしまう誘惑は強い。専門家がその誘惑に負けるのは、無知だからではなく、期待に応えたいからだ。皮肉なことに、誠実であろうとするほど言葉は歯切れが悪くなる。\n（　2　）、あいまいに言えばよいというものでもない。「場合による」で終わる助言は、線を引いていないという点で断定と変わらない。必要なのは、条件を明示したうえで言い切ることである。", "notas": [{"termino": "線引き", "glosa": "境目をはっきり決めること"}]}'::jsonb, null, null, '["文章の文法"]'::jsonb, 7),
  ('n1-bunshou_bunpou-0005', 'N1', 'bunshou_bunpou', 'n1-bb-g002', 1, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　2　）', null, '["かといって", "なぜなら", "そのうえ", "したがって"]'::jsonb, 0, '["理由の説明ではない", "付け足しではない", "前段の帰結にはならない"]'::jsonb, '{"es": "Viene de decir que la honestidad vuelve el lenguaje impreciso, y ahora frena esa deriva: «かといって».", "en": "It follows the point that honesty blurs the language, and now checks that drift: «かといって»."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 7),
  ('n1-kadai-0001', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人はこの後まず何をしますか。', null, '["仕様書を修正する", "業者に連絡する", "見積もりを取り直す", "部長に報告する"]'::jsonb, 0, '["連絡は修正の後", "見積もりは仕様が固まってから", "報告は数字が出てから"]'::jsonb, '{"es": "El presupuesto no se puede rehacer hasta que el pliego refleje el cambio, así que lo primero es corregirlo.", "en": "The quote can''t be redone until the spec reflects the change, so correcting it comes first."}'::jsonb, '["仕様が変わった → 仕様書の修正が先", "見積もりは仕様書を送ってから", "報告は数字が出そろってから"]'::jsonb, null, '{"intro": "会社で男の人と女の人が話しています。女の人はこの後まず何をしますか。", "turnos": [{"quien": "M", "texto": "例の件、先方から仕様の変更が入ったそうですね。"}, {"quien": "F", "texto": "ええ。見積もりを取り直さないといけません。"}, {"quien": "M", "texto": "でも、仕様書がまだ前のままでは、業者も出しようがないでしょう。"}, {"quien": "F", "texto": "あ、たしかに。先に直しておかないと。"}, {"quien": "M", "texto": "それができたら業者に送って、数字が出てから部長に報告しましょう。"}], "pregunta": "女の人はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 5),
  ('n1-point-0001', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人が今回の企画で最も重視したのは何ですか。', null, '["参加者が意見を言いやすいこと", "費用を抑えること", "時間を短くすること", "参加者を増やすこと"]'::jsonb, 0, '["費用は結果として下がっただけ", "時間はむしろ長くなった", "人数は増やさないと言っている"]'::jsonb, '{"es": "Dice que lo primero fue que la gente pudiera hablar; por eso redujo el aforo aunque alargara la sesión.", "en": "He says the priority was that people could speak; that''s why he cut attendance even though it lengthened the session."}'::jsonb, '["人数は絞った → 増やしていない", "時間は長くなった → 短縮ではない", "発言しやすさを最優先"]'::jsonb, null, '{"intro": "男の人が企画について話しています。男の人が今回の企画で最も重視したのは何ですか。", "turnos": [{"quien": "M", "texto": "今回は思い切って参加者を二十名に絞りました。人数を増やせば会は大きく見えますが、それでは黙る人が出ます。時間も予定より三十分長くなりましたが、最後まで全員が一度は発言していました。費用は結果的に下がりましたけれど、そこは狙いではありません。"}], "pregunta": "男の人が今回の企画で最も重視したのは何ですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 5),
  ('n1-gaiyou-0001', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', 'この人は何について話していますか。', null, '["失敗の記録を残すことの意味", "会議の進め方", "新人の教育方法", "記録係の選び方"]'::jsonb, 0, '["会議は例として出ただけ", "教育の話ではない", "係の話ではない"]'::jsonb, '{"es": "Todo el discurso gira en torno a por qué conviene anotar los fallos: sin registro se repiten.", "en": "The whole talk is about why failures should be written down: without a record they repeat."}'::jsonb, '["うまくいった話は残る", "失敗は忘れられる", "同じ失敗をくり返す"]'::jsonb, null, '{"intro": "会社で女の人が話しています。", "turnos": [{"quien": "F", "texto": "うまくいったことは、放っておいても語り継がれます。問題は、うまくいかなかったことのほうです。誰も進んで書き残そうとしませんし、読み返すのも気が重い。ですが、記録がなければ、二年もすれば同じところで同じようにつまずきます。私たちが残すべきなのは成功例ではなく、どこで判断を誤ったかのほうなのです。"}], "pregunta": "この人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 5),
  ('n1-sokuji-0001', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'お忙しいところ恐れ入りますが、少々よろしいでしょうか。', null, '["ええ、かまいませんよ。", "ええ、恐れ入ります。", "いえ、少々です。"]'::jsonb, 0, '["謝る側の言葉を返している", "答えになっていない"]'::jsonb, '{"es": "Piden un momento con fórmula de disculpa: se concede con かまいません.", "en": "They''re asking for a moment with an apologetic formula: grant it with かまいません."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "お忙しいところ恐れ入りますが、少々よろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 4),
  ('n1-sokuji-0002', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この案、私が言うのもなんですが、少し無理があるのでは。', null, '["はい、無理を言いました。", "いえ、おっしゃるとおりです。", "では、私が言いましょう。"]'::jsonb, 1, '["無理を言ったのは相手ではない", "言う人の話ではない"]'::jsonb, '{"es": "Señalan con reservas que el plan cojea: se acepta la crítica con おっしゃるとおりです.", "en": "They hedge a criticism of the plan: you accept it with おっしゃるとおりです."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "この案、私が言うのもなんですが、少し無理があるのでは。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 5),
  ('n1-sokuji-0003', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'あの件、あれからどうなりましたっけ。', null, '["では、片づけておきます。", "まだ聞いていないんですか。", "先週、無事に片づきましたよ。"]'::jsonb, 2, '["これからの話にしている", "質問に答えていない"]'::jsonb, '{"es": "Preguntan por el desenlace de algo pasado: se responde contando cómo acabó.", "en": "They ask how something already under way turned out: you answer with the outcome."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "あの件、あれからどうなりましたっけ。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 4),
  ('n1-kadai-0002', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の人は この後 まず 何を しますか。', null, '["会場を押さえる", "招集通知の原稿を仕上げる", "想定問答を作る", "印刷会社に納期を確認する"]'::jsonb, 1, '["すでに済んでいる", "後に回すと述べている", "納期はすでに伝えられている"]'::jsonb, '{"es": "El plazo real no es el legal sino el de la imprenta, que cierra esta semana.", "en": "The binding deadline isn''t the legal one but the printer''s, which closes this week."}'::jsonb, '["会場は押さえ済み", "法定期限より印刷会社の納期が先に来る", "想定問答は後回し"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 話して います。男の人は この後 まず 何を しますか。", "turnos": [{"quien": "F", "texto": "来月の株主総会の件、会場の押さえは?"}, {"quien": "M", "texto": "済んでいます。あとは招集通知の発送と、想定問答の作成ですね。"}, {"quien": "F", "texto": "通知には法定の期限があるでしょう。何日前まで?"}, {"quien": "M", "texto": "二週間前までです。まだ余裕があります。"}, {"quien": "F", "texto": "いえ、印刷会社の受付が今週いっぱいで締まると聞きました。原稿が間に合わないと、発送そのものが遅れます。"}, {"quien": "M", "texto": "では、想定問答は後に回して、先に原稿を仕上げます。"}], "pregunta": "男の人はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 7),
  ('n1-kadai-0003', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '学生は この後 まず 何を しますか。', null, '["図の解像度を上げる", "参考文献の書式を直す", "共著者に返事を督促する", "論文を投稿する"]'::jsonb, 2, '["承諾を得たあとでよいと言われた", "掲載が決まってからでよいと言われた", "承諾がないと投稿できない"]'::jsonb, '{"es": "Sin el consentimiento de todos los coautores no se puede enviar nada.", "en": "Without every co-author''s consent nothing can be submitted."}'::jsonb, '["書式は掲載決定後でよい", "共著者の承諾がないと投稿できない", "図はそのあと"]'::jsonb, null, '{"intro": "大学で 教授と 学生が 話して います。学生は この後 まず 何を しますか。", "turnos": [{"quien": "M", "texto": "投稿の前に、図の解像度を上げておいてください。"}, {"quien": "F", "texto": "はい。あと、参考文献の書式も直します。"}, {"quien": "M", "texto": "それは掲載が決まってからで構いません。それより、共著者全員の承諾はもらいましたか。"}, {"quien": "F", "texto": "まだ二人から返事が来ていません。"}, {"quien": "M", "texto": "承諾がないと投稿そのものができません。督促してください。図はそのあとで結構です。"}], "pregunta": "学生はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 7),
  ('n1-kadai-0004', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '社員は この後 まず 何を しますか。', null, '["商品を並べ替える", "商品を数える", "数える用紙を印刷する", "レジの数字を合わせる"]'::jsonb, 3, '["開店前でよいと言われた", "数字が合ってからでないと原因が分からなくなる", "すでに印刷してある"]'::jsonb, '{"es": "Si se cuenta con la caja descuadrada, después no se sabrá de dónde viene la diferencia.", "en": "Counting with the till out of balance makes the discrepancy impossible to trace afterwards."}'::jsonb, '["用紙は印刷済み", "並べ替えは開店前でよい", "レジが合わないまま数えると原因が分からない"]'::jsonb, null, '{"intro": "店で 店長と 社員が 話して います。社員は この後 まず 何を しますか。", "turnos": [{"quien": "F", "texto": "明日の棚卸し、準備はどう?"}, {"quien": "M", "texto": "数える用紙は印刷しました。あとは商品を並べ替えるだけです。"}, {"quien": "F", "texto": "並べ替えは開店前で構いません。それより、レジの締めの数字が合っていないと聞きましたが。"}, {"quien": "M", "texto": "あ、はい。千円ほど。"}, {"quien": "F", "texto": "棚卸しの前に、そこを合わせておいてください。合わないまま数えると、原因が分からなくなります。"}], "pregunta": "社員はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 7),
  ('n1-kadai-0005', 'N1', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の人は この後 まず 何を しますか。', null, '["勤務先に書類を頼む", "契約書に署名する", "物件をもう一度見る", "保証会社の審査を受ける"]'::jsonb, 0, '["審査の前には進めない", "見学の話は出ていない", "書類がそろってからになる"]'::jsonb, '{"es": "El examen no arranca hasta tener los papeles, y el del ingreso lo emite la empresa.", "en": "The screening can''t start until the papers are in, and the income one comes from his employer."}'::jsonb, '["審査は書類がそろってから", "収入を証明する書類が必要", "先に勤務先へ頼む"]'::jsonb, null, '{"intro": "不動産屋で 男の人と 女の人が 話して います。男の人は この後 まず 何を しますか。", "turnos": [{"quien": "F", "texto": "こちらの物件でよろしければ、お申し込みに進みます。"}, {"quien": "M", "texto": "お願いします。手続きには何が必要ですか。"}, {"quien": "F", "texto": "身分を証明するものと、収入を証明する書類ですね。あと、保証会社の審査があります。"}, {"quien": "M", "texto": "審査はどのくらいかかりますか。"}, {"quien": "F", "texto": "二、三日です。ただ、書類がそろってからになりますので、先に勤務先へお願いされたほうがよろしいかと。"}, {"quien": "M", "texto": "分かりました。"}], "pregunta": "男の人はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 7),
  ('n1-point-0002', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人が 計画を 見直したのは なぜですか。', null, '["上司の指示があったから", "法改正の施行時期がずれたから", "数字が甘かったから", "法改正の内容が変わったから"]'::jsonb, 1, '["上からではないと言っている", "むしろ堅めに見ていたと言っている", "中身は変わっていないと言っている"]'::jsonb, '{"es": "Sólo se movió la fecha de entrada en vigor, y eso reordenó todo el flujo de caja.", "en": "Only the date of entry into force moved, and that reshuffled the whole cash-flow order."}'::jsonb, '["数字は堅めに見ていた", "上からの指示ではない", "施行時期だけが一年ずれた"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 話して います。女の人が 計画を 見直したのは なぜですか。", "turnos": [{"quien": "M", "texto": "計画、作り直したそうですね。数字が甘かったんですか。"}, {"quien": "F", "texto": "数字は問題なかったんです。むしろ堅めに見ていました。"}, {"quien": "M", "texto": "では、上から何か。"}, {"quien": "F", "texto": "いえ。前提にしていた法改正が、施行時期だけ一年ずれたんです。中身は変わっていません。ただ、それだけで収支の順番が全部入れ替わってしまって。"}], "pregunta": "女の人が計画を見直したのはなぜですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 8),
  ('n1-point-0003', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人が 評価して いる 点は 何ですか。', null, '["効果を数字で示せること", "費用が安いこと", "存在すること自体が判断を変えること", "利用件数が多いこと"]'::jsonb, 2, '["数字で示せと言われると弱いと言っている", "費用の話はしていない", "年に数件だと言っている"]'::jsonb, '{"es": "Casi no se usa, y ese es el punto: saber que existe impide decisiones forzadas sobre el terreno.", "en": "It''s barely used, and that''s the point: knowing it exists stops forced decisions on the ground."}'::jsonb, '["利用は年に数件", "数字で効果を示すのは難しい", "あると分かるだけで無理な判断が減る"]'::jsonb, null, '{"intro": "男の人が 新しい 制度に ついて 話して います。男の人が 評価して いる 点は 何ですか。", "turnos": [{"quien": "M", "texto": "この制度、使う人は多くありません。年に数件でしょう。効果を数字で示せと言われると弱い。ただ、これがあると分かっているだけで、現場が無理な判断をしなくなるんです。使われないことに意味がある仕組みというのは、確かに存在します。"}], "pregunta": "男の人が評価している点は何ですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 8),
  ('n1-point-0004', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人が 講演の 依頼を 断ったのは なぜですか。', null, '["専門外だったから", "日程が合わなかったから", "報酬が少なかったから", "断定を求められたから"]'::jsonb, 3, '["専門そのものだったと言っている", "日程は空いていたと言っている", "報酬の話は出ていない"]'::jsonb, '{"es": "Le pedían conclusiones tajantes sobre algo aún en verificación.", "en": "They wanted flat conclusions about something still under verification."}'::jsonb, '["内容は専門そのもの", "日程も空いていた", "求められたのは結論の言い切り"]'::jsonb, null, '{"intro": "男の人と 女の人が 話して います。女の人が 講演の 依頼を 断ったのは なぜですか。", "turnos": [{"quien": "M", "texto": "断ったんですか。もったいない。"}, {"quien": "F", "texto": "内容は私の専門そのものでした。日程も空いていました。"}, {"quien": "M", "texto": "じゃあ、なぜ。"}, {"quien": "F", "texto": "主催者が求めていたのは、結論の言い切りだったんです。まだ検証中のことを、断定して話すわけにはいきません。"}], "pregunta": "女の人が講演の依頼を断ったのはなぜですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 8),
  ('n1-point-0005', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人の 見解が 分かれて いるのは どの点ですか。', null, '["何が記録に残っているかという認識", "撤退の判断を早くすべきかどうか", "撤退そのものの是非", "損失の大きさの見積もり"]'::jsonb, 0, '["早さには賛成だと述べている", "どちらも撤退を否定していない", "損失額の話は出ていない"]'::jsonb, '{"es": "Él cree que ya se registra; ella dice que se guarda el resultado, no el razonamiento.", "en": "He thinks it''s already recorded; she says what''s kept is the outcome, not the reasoning."}'::jsonb, '["早さには両者とも賛成", "男の人は記録を残していると考えている", "女の人は根拠が残っていないと言う"]'::jsonb, null, '{"intro": "会議で 男の人と 女の人が 話して います。二人の 見解が 分かれて いるのは どの点ですか。", "turnos": [{"quien": "M", "texto": "撤退の判断は早いほうがいい。傷が浅いうちに止めるべきです。"}, {"quien": "F", "texto": "早さには賛成です。ただ、早く止めた案件を、なぜ止めたのか残さないと、同じ判断を何度もやることになります。"}, {"quien": "M", "texto": "記録は残していますよ。"}, {"quien": "F", "texto": "結果は残っています。判断の根拠が残っていないんです。"}], "pregunta": "二人の見解が分かれているのはどの点ですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 9),
  ('n1-point-0006', 'N1', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は 何を 問題だと 考えて いますか。', null, '["参加者が少ないこと", "測る対象が適切でないこと", "満足度が低いこと", "研修の回数が多すぎること"]'::jsonb, 1, '["人数の話は出ていない", "九割を超えていると言っている", "回数の話は出ていない"]'::jsonb, '{"es": "Con satisfacción altísima y conducta sin cambiar, el indicador elegido oculta el fallo.", "en": "With sky-high satisfaction and unchanged behaviour, the chosen metric hides the failure."}'::jsonb, '["満足度は毎回九割超", "三か月後の行動は変わっていない", "満足度を測る限り差が見えない"]'::jsonb, null, '{"intro": "男の人が 研修に ついて 話して います。男の人は 何を 問題だと 考えて いますか。", "turnos": [{"quien": "M", "texto": "研修の満足度は毎回九割を超えています。参加者はよかったと言ってくださる。ただ、三か月後に行動が変わっているかを調べると、ほとんど変わっていない。満足度を測っている限り、この差は見えません。測る対象を変えないと、いつまでも成功しているように見えてしまうんです。"}], "pregunta": "男の人は何を問題だと考えていますか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 9),
  ('n1-gaiyou-0002', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は 何に ついて 話して いますか。', null, '["窓が果たす役割", "設計で最も時間をかけている点", "建築という仕事の歴史", "廊下の幅の決め方"]'::jsonb, 1, '["窓は例として出ただけ", "歴史には触れていない", "幅は結果として決まると述べただけ"]'::jsonb, '{"es": "Explica que lo que realmente diseña no es el movimiento sino los puntos donde la gente se detiene.", "en": "He explains that what he really designs isn''t movement but the points where people stop."}'::jsonb, '["立ち止まる場所を決めるのに時間をかける", "廊下や窓はそこから決まる", "設計しているのは止まる場所"]'::jsonb, null, '{"intro": "建築家が 話して います。", "turnos": [{"quien": "M", "texto": "私たちが設計するとき、いちばん時間をかけるのは、人が立ち止まる場所を決めることです。廊下の幅や窓の位置は、そこから決まっていきます。動線という言葉は移動を思わせますが、実際に設計しているのは、止まる場所のほうなんです。"}], "pregunta": "男の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 8),
  ('n1-gaiyou-0003', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何に ついて 話して いますか。', null, '["編集者の一日の仕事", "文章の書き出しの重要性", "原稿を読むときに注目する点", "章の数の決め方"]'::jsonb, 2, '["仕事全体の話はしていない", "最初の一行より切り方を見ると述べている", "数ではなく位置の話"]'::jsonb, '{"es": "Lo que mira no es el arranque sino dónde el autor corta: ahí se ve lo que quiere decir.", "en": "What she looks at isn''t the opening but where the writer cuts: that''s where the intent shows."}'::jsonb, '["最初の一行より切り方を見る", "段落と章の区切り位置", "区切った位置に意図が表れる"]'::jsonb, null, '{"intro": "編集者が 話して います。", "turnos": [{"quien": "F", "texto": "原稿を読むとき、私は最初の一行より、切り方を見ます。どこで段落を切り、どこで章を終えるか。書き手が何を言いたいかは、書いた内容よりも、どこで区切ったかに表れるからです。"}], "pregunta": "女の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 8),
  ('n1-gaiyou-0004', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は 何に ついて 話して いますか。', null, '["病気の治し方", "分かりやすい話し方の技術", "患者の数の変化", "説明の目的についての考えの変化"]'::jsonb, 3, '["治療そのものの話はしていない", "分かりやすさを最優先しなくなったと述べている", "人数の話は出ていない"]'::jsonb, '{"es": "Antes priorizaba la claridad; ahora, marcar lo que no se sabe, para que el paciente vuelva a llamar.", "en": "He used to prioritise clarity; now, flagging what isn''t known, so the patient calls back."}'::jsonb, '["以前は分かりやすさが最優先", "今は分からない部分を伝える", "目的は納得ではなく次の連絡"]'::jsonb, null, '{"intro": "医師が 話して います。", "turnos": [{"quien": "M", "texto": "患者さんに説明するとき、以前は分かりやすさを最優先していました。今は、分からない部分を分からないと伝えることを優先しています。全部分かった気になって帰られると、途中で不安になったときに相談してもらえない。説明の目的は納得ではなく、次に連絡してもらうことなんです。"}], "pregunta": "男の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 9),
  ('n1-gaiyou-0005', 'N1', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何に ついて 話して いますか。', null, '["空振りをどう考えるべきか", "天気を予測する技術", "過去の被害の大きさ", "避難のときの持ち物"]'::jsonb, 0, '["技術の説明はしていない", "被害は比較のために触れただけ", "持ち物の話はしていない"]'::jsonb, '{"es": "Su tesis: evitar la falsa alarma obliga a avisar tarde, así que hay que explicar que fallar así no es fallar.", "en": "Her thesis: avoiding false alarms forces late warnings, so it must be explained that such a miss isn''t a failure."}'::jsonb, '["空振りへの批判は強い", "空振りを減らすと必ず出し遅れる", "空振りは失敗ではないと説明すべき"]'::jsonb, null, '{"intro": "防災の 担当者が 話して います。", "turnos": [{"quien": "F", "texto": "避難の呼びかけで難しいのは、空振りを恐れることです。出さなかった場合の被害は誰の目にも見えますが、出したのに何も起きなかった場合の批判も強い。しかし、空振りを減らそうとすると、必ず出し遅れます。私たちが説明すべきなのは、空振りは失敗ではないということのほうです。"}], "pregunta": "女の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 9),
  ('n1-sokuji-0004', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '先方へのご連絡、私のほうでやっておきましょうか。', null, '["助かります、お願いします。", "ええ、私が伺いました。", "いえ、こちらこそ失礼しました。"]'::jsonb, 0, '["これからの申し出に過去形で答えている", "謝罪の返事になっている"]'::jsonb, '{"es": "Te ofrecen encargarse: se acepta y se agradece.", "en": "They offer to handle it: you accept and thank them."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "先方へのご連絡、私のほうでやっておきましょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 7),
  ('n1-sokuji-0005', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この件、来週までお待ちいただくわけにはいきませんか。', null, '["はい、来週いただきました。", "事情は分かりました。何とかします。", "いいえ、お待ちしております。"]'::jsonb, 1, '["受け取った話になっている", "待つのは相手ではなくこちら"]'::jsonb, '{"es": "Piden aplazamiento: se responde aceptando la circunstancia.", "en": "They''re asking for a delay: you answer by accepting the circumstance."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "この件、来週までお待ちいただくわけにはいきませんか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 8),
  ('n1-sokuji-0006', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '部長がお呼びですが、今よろしいでしょうか。', null, '["はい、お呼びになります。", "いいえ、呼んでおきます。", "はい、すぐ伺います。"]'::jsonb, 2, '["呼ぶのは部長で、答える側ではない", "呼ぶ立場が逆になっている"]'::jsonb, '{"es": "Te llaman: se responde con el humilde 伺う, «voy enseguida».", "en": "You''re being summoned: you answer with the humble 伺う, ''I''ll come right away''."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "部長がお呼びですが、今よろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 7),
  ('n1-sokuji-0007', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '先日いただいた資料、大変参考になりました。', null, '["お役に立てて何よりです。", "まだ拝見しておりません。", "参考にさせていただきます。"]'::jsonb, 0, '["渡した側の返事になっていない", "これから読む側の言い方"]'::jsonb, '{"es": "Te dan las gracias por lo que enviaste: se responde alegrándose de que sirviera.", "en": "They thank you for what you sent: you answer glad it was of use."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "先日いただいた資料、大変参考になりました。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 7),
  ('n1-sokuji-0008', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この案、通ると思いますか。', null, '["ええ、通していただきました。", "正直、五分五分でしょうね。", "いえ、まだ提出しておりません。"]'::jsonb, 1, '["すでに決まった話になっている", "見通しを答えていない"]'::jsonb, '{"es": "Preguntan una previsión, así que se responde con una estimación.", "en": "They ask for a forecast, so you answer with an estimate."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "この案、通ると思いますか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 8),
  ('n1-sokuji-0009', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'お忙しいところ恐れ入りますが、少々お時間よろしいでしょうか。', null, '["いいえ、お忙しいですよ。", "ええ、恐れ入りました。", "ええ、五分ほどなら。"]'::jsonb, 2, '["忙しいのは答える側で、相手ではない", "相手の前置きをそのまま返している"]'::jsonb, '{"es": "Piden un momento: se concede acotándolo.", "en": "They ask for a moment: you grant it with a limit."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "お忙しいところ恐れ入りますが、少々お時間よろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 7),
  ('n1-sokuji-0010', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '上司に確認が取れ次第、こちらからご連絡いたします。', null, '["では、お待ちしております。", "もうご連絡は来ましたか。", "こちらこそ確認いたしました。"]'::jsonb, 0, '["これから連絡すると言われている", "確認するのは相手の側"]'::jsonb, '{"es": "Van a llamarte cuando lo confirmen: se responde quedando a la espera.", "en": "They''ll call once confirmed: you answer that you''ll wait."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "上司に確認が取れ次第、こちらからご連絡いたします。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 7),
  ('n1-sokuji-0011', 'N1', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'その件でしたら、私では分かりかねます。', null, '["そうですか、では分かりました。", "では、どなたに伺えばよろしいでしょうか。", "分かりかねて申し訳ありません。"]'::jsonb, 1, '["用件が解決していないまま終わる", "謝るのは分からないと言った側"]'::jsonb, '{"es": "No lo sabe: lo natural es preguntar a quién dirigirse.", "en": "They don''t know: the natural move is to ask who does."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "その件でしたら、私では分かりかねます。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 8),
  ('n1-tougou_choukai-0001', 'N1', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人は どの 対策を 選びましたか。', null, '["納期を延ばす", "工程を減らす", "まだ決まっていない", "人を増やす"]'::jsonb, 0, '["品質に手をつけるのは避けたいと言っている", "頭を下げに行くと決めている", "来期まで採用ができない"]'::jsonb, '{"es": "Calidad está vetada por el antecedente y contratar no llega a tiempo: queda pedir prórroga al cliente.", "en": "Quality is off-limits after last time and hiring can''t arrive in time: asking the client for more time is what''s left."}'::jsonb, '["採用は来期まで不可", "品質検査を省くのは避けたい", "納期延長には取引先の了解が要る"]'::jsonb, null, '{"intro": "会社で 女の人が 三つの 対策を 説明して います。そのあと 男の人と 話して います。", "turnos": [{"quien": "F", "texto": "対策は三つ考えられます。一つ目は人を増やす案。効果は確実ですが、来期まで採用ができません。二つ目は工程を減らす案。今すぐ着手できますが、品質検査の一部を省くことになります。三つ目は納期を延ばす案。無理は生じませんが、取引先の了解が要ります。"}, {"quien": "M", "texto": "品質に手をつけるのは避けたい。前回それで信用を失いました。"}, {"quien": "F", "texto": "では、人を増やすか、納期を延ばすかですね。"}, {"quien": "M", "texto": "来期まで待てる状況ではありません。頭を下げに行きましょう。"}], "pregunta": "二人はどの対策を選びましたか。"}'::jsonb, null, '["統合理解"]'::jsonb, 8),
  ('n1-tougou_choukai-0002', 'N1', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人は どちらに 決めましたか。', null, '["両方を見に行く", "駅から近い部屋", "歩いて十五分の部屋", "まだ決めていない"]'::jsonb, 1, '["見学の話は出ていない", "階段しかないので荷物が大変", "決めると述べている"]'::jsonb, '{"es": "Los dos mil yenes pesaban hasta que aparecen las escaleras: eso es diario, y decide.", "en": "The two thousand yen mattered until the stairs came up: that''s a daily cost, and it decides it."}'::jsonb, '["近い部屋は二万円高い", "女の人は毎日通勤する", "遠いほうは階段しかない"]'::jsonb, null, '{"intro": "男の人と 女の人が 引っ越し先に ついて 話して います。", "turnos": [{"quien": "M", "texto": "駅から近い部屋は家賃が高いね。歩いて十五分のところなら二万円安い。"}, {"quien": "F", "texto": "私は毎日通勤だから、近いほうが助かる。"}, {"quien": "M", "texto": "僕は家で働く日が週三日だし、二万円は大きいよ。"}, {"quien": "F", "texto": "でも、遠いほうは階段しかないって書いてあった。荷物を運ぶのが大変。"}, {"quien": "M", "texto": "そうか。それは毎日のことだね。じゃあ、高くても近いほうにしよう。"}], "pregunta": "二人はどちらに決めましたか。"}'::jsonb, null, '["統合理解"]'::jsonb, 8),
  ('n1-tougou_choukai-0003', 'N1', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人が 最後に 意見の 一致を 見たのは どの点ですか。', null, '["調査を十年続けたこと", "データが不十分だったこと", "言い切らなかった態度を評価すること", "結論が当たり前だったこと"]'::jsonb, 2, '["続けたことは前段で触れた別の点", "不十分だとは述べていない", "女の人は結論より途中を評価している"]'::jsonb, '{"es": "Él acepta justo lo último que ella dice: no afirmar de más, sabiendo el límite, es lo que da confianza.", "en": "He agrees with her final point: not overclaiming, knowing the limit, is what earns trust."}'::jsonb, '["男の人は結論が当たり前だと感じた", "女の人は途中のデータを評価", "限界を知りつつ言い切らない態度に同感"]'::jsonb, null, '{"intro": "講演を 聞いた あと、男の人と 女の人が 話して います。", "turnos": [{"quien": "M", "texto": "面白かったけど、結論は当たり前だったね。"}, {"quien": "F", "texto": "私は逆で、結論より途中のデータが良かった。あの調査、十年続けているんでしょう。"}, {"quien": "M", "texto": "続けたこと自体はすごい。ただ、そこから言えることは限られる。"}, {"quien": "F", "texto": "限られると分かったうえで言い切らなかったのが、私は信用できると思った。"}, {"quien": "M", "texto": "なるほど。そこは同感かな。"}], "pregunta": "二人が最後に意見の一致を見たのはどの点ですか。"}'::jsonb, null, '["統合理解"]'::jsonb, 9),
  ('n1-tanbun-0001', 'N1', 'tanbun', 'n1-tanbun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者によると、助言が役に立たないと感じられる主な原因は何か。', null, '["問題の輪郭がどこまで見えているかが両者で異なるから", "求める側に専門知識がないから", "助言する側の説明が長すぎるから", "専門家の知識が不足しているから"]'::jsonb, 0, '["知識の差ではないと本文が否定している", "本文にない", "本文にない"]'::jsonb, '{"es": "El texto dice expresamente que no es una diferencia de conocimiento, sino de hasta dónde se ve el contorno del problema.", "en": "The text says explicitly it isn''t a knowledge gap but a difference in how far each side can see the shape of the problem."}'::jsonb, null, '{"texto": "専門家の助言が役に立たないと感じられるとき、その原因は助言の中身ではなく、前提の共有にあることが多い。助言する側は問題をすでに整理し終えた地点から話す。一方、助言を求める側は、まだ何が問題なのかを言葉にできていない段階にいる。両者の間にあるのは知識の差というより、問題の輪郭がどこまで見えているかの差なのである。したがって、有効な助言はしばしば答えの形をとらず、問いの立て直しという形をとる。", "notas": [{"termino": "輪郭", "glosa": "だいたいの形、外側の線"}]}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n1-tanbun-0002', 'N1', 'tanbun', 'n1-tanbun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は記録の意味をどこにあると考えているか。', null, '["後で読み返せること", "書く過程で出来事を整理し直すこと", "他人に伝わること", "正確さが保証されること"]'::jsonb, 1, '["読み返されるのは一部だと本文が否定している", "本文にない", "本文にない"]'::jsonb, '{"es": "El valor está en el propio acto de escribir, que obliga a reordenar lo ocurrido, aunque nadie vuelva a leerlo.", "en": "The value lies in the act of writing itself, which forces you to reorder what happened, even if nobody reads it again."}'::jsonb, null, '{"texto": "記録を残すことの価値は、後で読み返すことにあるとされがちだ。しかし実際に読み返される記録はごく一部にすぎない。それでも記録に意味があるのは、書く過程そのものが出来事を整理させるからである。何が起きたかを言葉にしようとした時点で、人はすでに一度その出来事を理解し直している。読まれない記録もまた、書かれた時点で確かに働いているのである。日記が続かないことを悔やむ人は多いが、悔やむ必要はない。続かなかった日々の分も、書いた日の理解は残っているからだ。", "notas": []}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n1-chuubun-0001', 'N1', 'chuubun', 'n1-chuubun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は「問題は能力の総量ではなく、その配分なのである」と述べているが、どういうことか。', null, '["道具は能力を奪うと同時に、注意の向け先を移すということ", "道具を使えば誰でも能力が高まるということ", "道具によって能力の合計が増えるということ", "能力は測ることができないということ"]'::jsonb, 0, '["本文にない", "総量の話ではないと本文が否定している", "本文にない"]'::jsonb, '{"es": "El segundo párrafo lo explica: la herramienta quita una capacidad y a la vez desplaza hacia dónde va la atención.", "en": "The second paragraph explains it: the tool takes away one ability while shifting where attention goes."}'::jsonb, null, '{"texto": "新しい技術が現れるたびに、それが人間の能力を奪うのではないかという議論が起こる。計算機が普及したときには暗算の力が、地図の案内装置が広まったときには方向感覚が失われると言われた。実際、それらの能力は平均的には低下しているのかもしれない。\nしかし、失われたものだけを数えるのは公平ではない。道具は能力を奪うと同時に、注意を向ける先を移す。暗算に使っていた資源は別の思考に回され、地図を読むことに費やしていた注意は、目的地で何をするかに向けられる。問題は能力の総量ではなく、その配分なのである。\nもっとも、この配分が本人の選択によるものかどうかは別の話だ。道具が変えるのは可能性の形であって、それをどう使うかまでは決めてくれない。空いた資源が何にも向けられなければ、それは単に失われただけである。技術を批判するにせよ擁護するにせよ、この区別を曖昧にしたままでは議論は進まないだろう。\n私たちが問うべきなのは、その道具が何を肩代わりしてくれるかではない。肩代わりされた分の時間と注意を、自分が何に使うつもりでいるのかである。そこまで含めて考えたときにはじめて、道具は能力を奪うものではなく、選択を突きつけるものとして立ち現れてくる。", "notas": [{"termino": "配分", "glosa": "分け方、割りふり"}]}'::jsonb, null, null, '["中文"]'::jsonb, 5),
  ('n1-chuubun-0002', 'N1', 'chuubun', 'n1-chuubun-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が最後の段落で言いたいことは何か。', null, '["技術は批判されるべきだ", "空いた資源をどう使うかは道具が決めてくれない", "道具は使わないほうがよい", "技術は擁護されるべきだ"]'::jsonb, 1, '["どちらの立場も取っていない", "本文にない", "どちらの立場も取っていない"]'::jsonb, '{"es": "Dice que la herramienta cambia la forma de lo posible pero no decide el uso: si el recurso liberado no va a nada, simplemente se perdió.", "en": "It says the tool changes what''s possible but doesn''t decide the use: if the freed resource goes nowhere, it''s simply lost."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 5),
  ('n1-tougou-0001', 'N1', 'tougou', 'n1-tougou-g001', 0, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '会議について、AとBが共通して認めていることは何か。', null, '["資料を事前に配ると会議の進み方が変わること", "会議は短いほどよいということ", "参加者全員が必ず資料を読むこと", "会議は判断の場にすべきでないこと"]'::jsonb, 0, '["Bは短さを目的にすることを批判している", "Bは読んでこない人がいると述べている", "Aは判断の場になると肯定している"]'::jsonb, '{"es": "Los dos parten de que repartir el material antes cambia cómo transcurre la reunión; discrepan en si ese cambio es bueno.", "en": "Both take it as given that handing out material beforehand changes how the meeting runs; they disagree on whether that change is good."}'::jsonb, null, '{"texto": "A\n会議の時間を短くするには、資料を事前に配ることだ。読めば分かることを読み上げる時間ほど無駄なものはない。参加者が目を通してきていれば、会議は判断の場になる。読んでこない人がいるという反論はあるだろうが、それは会議の問題ではなく参加者の問題である。\n\nB\n事前配布には限界がある。読んでくる人と読んでこない人がいれば、会議は前者の理解を前提に進み、後者は黙るしかない。結果として発言する人が固定され、決定の質はかえって下がる。短くすることだけを目的にすると、参加していない人を作り出してしまう。時間の長さより、誰が話せているかを見るべきだ。", "notas": []}'::jsonb, null, null, '["統合理解"]'::jsonb, 5),
  ('n1-tougou-0002', 'N1', 'tougou', 'n1-tougou-g001', 1, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '読んでこない参加者について、AとBの立場はどうちがうか。', null, '["Aは会議の問題だとし、Bは参加者側の問題だとしている", "Aは参加者側の問題だとし、Bは会議の質が下がる原因になるとしている", "AもBも参加者側の問題だとしている", "AもBも会議の運営の問題だとしている"]'::jsonb, 1, '["AとBが逆", "Bは会議の側の問題として扱っている", "Aは参加者の問題だと明言している"]'::jsonb, '{"es": "A lo despacha como problema del participante; B dice que produce gente que no participa y baja la calidad de la decisión.", "en": "A dismisses it as the participant''s problem; B says it manufactures non-participants and lowers decision quality."}'::jsonb, null, null, null, null, '["統合理解"]'::jsonb, 5),
  ('n1-tanbun-0003', 'N1', 'tanbun', 'n1-tanbun-g003', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は 制度づくりの 何を 問題に して いるか。', null, '["条文が複雑になりすぎること", "技術的な検討が不足していること", "少数を防ぐために多数に負担をかけていること", "例外への備えが足りないこと"]'::jsonb, 2, '["複雑さそのものは論点ではない", "技術の問題ではないと述べている", "備えすぎることを問題にしている"]'::jsonb, '{"es": "El coste de blindarse contra unos pocos lo pagan todos los demás en trámites.", "en": "The cost of guarding against a few is paid by everyone else in paperwork."}'::jsonb, null, '{"texto": "制度を作るとき、私たちは例外を先に考えがちである。悪用する者が出たらどうするか、想定外の事態にどう備えるか。慎重さの表れではあるが、そうして積み上げた条文は、たいてい大多数の善意の利用者を疑う形になる。少数の逸脱を防ぐ代償として、多数に手間を課しているのだ。どちらを選ぶかは価値判断であって、技術的な最適化の問題ではない。設計者がこの二つを混同したとき、制度は誰のためのものか分からなくなる。", "notas": [{"termino": "逸脱", "glosa": "決まりから外れること"}]}'::jsonb, null, null, '["短文"]'::jsonb, 7),
  ('n1-tanbun-0004', 'N1', 'tanbun', 'n1-tanbun-g004', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考えに 合う ものは どれか。', null, '["一度目のほうが正確に理解できる", "同じ話は繰り返すべきではない", "効率を上げることが最も大切だ", "反復には一度目にないものがある"]'::jsonb, 3, '["一度目は筋を追うので精一杯だと述べている", "反復の価値を認めている", "効率を理由に削ることを批判している"]'::jsonb, '{"es": "La segunda vez muestra las vacilaciones y las correcciones que la primera tapa.", "en": "The second time reveals the hesitations and corrections the first one hides."}'::jsonb, null, '{"texto": "同じ話を二度聞かされるのは退屈だが、二度目に初めて気づくことは少なくない。一度目は筋を追うので精一杯で、語り手がどこで言いよどんだか、どの語を選び直したかまでは目に入らない。情報としては重複でも、経験としては別物である。効率を理由に反復を削っていくと、この二度目だけが与えてくれるものまで、気づかないうちに一緒に削れてしまう。削られたことにさえ気づかないところが、効率という基準のこわさである。", "notas": [{"termino": "言いよどむ", "glosa": "言葉に詰まって止まる"}]}'::jsonb, null, null, '["短文"]'::jsonb, 7),
  ('n1-chuubun-0003', 'N1', 'chuubun', 'n1-chuubun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「訳せない語が ある」という 言い方が 不正確なのは、なぜか。', null, '["語の数が言語によって違うから", "読者が立ち止まってしまうから", "近い意味の語はたいてい存在するから", "訳者の技術の問題にすぎないから"]'::jsonb, 2, '["語数の差はその後に述べる別の問題", "立ち止まるのは訳し方の結果", "技術の問題だとは述べていない"]'::jsonb, '{"es": "El texto lo dice: casi siempre hay una palabra próxima; el problema está en la red de relaciones, no en la palabra.", "en": "The text says it: a near-equivalent almost always exists; the problem lies in the web of relations, not the word."}'::jsonb, null, '{"texto": "翻訳は言い換えではない、とよく言われる。しかし、では何なのかと問われると、答えは案外難しい。\n訳せない語がある、という言い方は少し不正確である。どんな語にも、近い意味の語はたいてい存在する。問題は語そのものではなく、その語が置かれている網の目のほうにある。ある言語で一語で済むことが、別の言語では三語を要する。そのとき増えた二語分の重さが、原文にはなかった強調として読者に届いてしまう。一語のまま置けば足りず、三語にすれば重い。訳者はその間で毎回選び直している。\nだから熟練した訳者ほど、語ではなく速度を訳そうとする。原文がさらりと通り過ぎた場所は、訳文でもさらりと通り過ぎなければならない。意味が正しくても、そこで読者を立ち止まらせてしまえば、訳としては失敗である。\nこれは文章に限った話ではないだろう。人の話を別の人に伝えるとき、私たちは無意識に語を補う。補ったぶんだけ、元の話にはなかった力点が生まれる。悪意はない。ただ、言葉は足したぶんだけ、必ず何かを主張してしまう。伝言が伝言でなくなるのは、たいていこの瞬間である。", "notas": [{"termino": "網の目", "glosa": "たがいにつながり合った関係"}]}'::jsonb, null, null, '["中文"]'::jsonb, 7),
  ('n1-chuubun-0004', 'N1', 'chuubun', 'n1-chuubun-g002', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「速度を 訳す」とは どういう ことか。', null, '["意味の正確さを最優先すること", "原文と同じ場所で読者を立ち止まらせること", "できるだけ短く訳すこと", "原文が軽く通る場所を訳文でも軽く通すこと"]'::jsonb, 3, '["意味が正しくても失敗はあると述べている", "立ち止まらせないことが目的", "長さの問題ではない"]'::jsonb, '{"es": "Se trata de reproducir dónde el texto corre y dónde pesa, no sólo qué dice.", "en": "It''s about reproducing where the text runs light and where it weighs, not only what it says."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 7),
  ('n1-chuubun-0005', 'N1', 'chuubun', 'n1-chuubun-g003', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '古い 写真の 人々の 顔が 似て 見えるのは、なぜだと 述べて いるか。', null, '["誰もカメラを見ていないから", "写真の技術が古いから", "同じ交差点に立っているから", "服装や髪型が揃っているから"]'::jsonb, 0, '["技術の話は出ていない", "場所は同じだが理由ではない", "最初はそう思ったが理由は別だと述べている"]'::jsonb, '{"es": "Descarta explícitamente la ropa: lo que iguala esos rostros es no saberse observados.", "en": "He explicitly rules out clothing: what levels those faces is not knowing they''re watched."}'::jsonb, null, '{"texto": "町の古い写真を見せてもらう機会があった。今と同じ交差点が写っているのに、そこにいる人々の顔は、なぜかどれも似て見える。服装や髪型が揃っているせいだと最初は思った。しかし、よく見ると理由は別のところにある。誰もカメラを見ていないのだ。撮る側と撮られる側の距離も、今よりずっと遠かったのだろう。\n写真に撮られることが珍しかった時代、人はカメラの存在にそもそも気づかなかった。だから、そこに写っているのは、見られていない人間の顔である。今の写真に写るのは、見られていることを知っている人間の顔だ。この差は、服装の差よりはるかに大きい。撮られ慣れた顔には、どこかに構えがある。\n記録が増えれば、その時代がよく分かるとはかぎらない。撮られることを前提にした振る舞いばかりが残れば、記録の量に反比例して、素の姿は見えなくなっていく。情報としては、当時よりはるかに多くのものが残るはずだ。それでも、残らないものは残らない。百年後の人が私たちの写真を見て何を読み取るのかは分からない。ただ、私たちが古い写真から受け取っているものとは、おそらく別のものだろう。", "notas": []}'::jsonb, null, null, '["中文"]'::jsonb, 7),
  ('n1-chuubun-0006', 'N1', 'chuubun', 'n1-chuubun-g003', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考えに 合う ものは どれか。', null, '["記録が増えるほどその時代はよく分かる", "記録が増えても素の姿は見えにくくなりうる", "昔の写真のほうが技術的に優れている", "写真は記録として信用できない"]'::jsonb, 1, '["とはかぎらないと述べている", "技術の比較はしていない", "信用できないとまでは述べていない"]'::jsonb, '{"es": "Si sólo queda la conducta de quien se sabe fotografiado, más volumen no da más verdad.", "en": "If only the behaviour of the photographed-aware survives, more volume doesn''t mean more truth."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 8),
  ('n1-chuubun-0007', 'N1', 'chuubun', 'n1-chuubun-g004', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '結果だけで 予測を 評価すると、どう なると 述べて いるか。', null, '["予測をする人が減る", "前提の誤りが見つけやすくなる", "確率を述べる人が不利になる", "予測が当たりやすくなる"]'::jsonb, 2, '["人数の話は出ていない", "見つけにくくなるという流れ", "評価の仕方は的中率を変えない"]'::jsonb, '{"es": "El que dice «setenta por ciento» pierde siempre; el que afirma tajante gana si acierta y se excusa si falla.", "en": "Whoever says ''seventy per cent'' always loses; the flat asserter wins on a hit and is excused on a miss."}'::jsonb, null, '{"texto": "予測が当たったかどうかで予測の質を測るのは、直感的には正しく思えるが、実は乱暴である。\n一度きりの出来事について、七割の確率で起きると述べた予測を考えてみればよい。実際に起きなかったとしても、その予測が誤りだったとはかぎらない。三割のほうが実現しただけかもしれないからだ。結果だけを見て評価すると、確率を口にする人は損をし、言い切る人が得をする。当たれば称賛され、外れても「誰にも分からなかった」で済むからである。この非対称が、慎重な予測を少しずつ表から追い出していく。\nでは何を見るべきか。一つは、予測が外れたときに、その人が何を修正したかである。前提のどこが違っていたかを特定できる人は、次の予測を改善できる。もう一つは、外れ方の分布だ。何度も予測する人であれば、七割と言った出来事のうち、およそ七割が実際に起きているかを確かめられる。どちらも地味な作業で、外から見て華やかなところはない。\nこの二つはどちらも、一回の的中とは無関係である。にもかかわらず、私たちが記憶するのは、劇的に当たった一回のほうだ。予測を評価する能力は、予測する能力よりも育ちにくい。", "notas": [{"termino": "分布", "glosa": "数がどのように散らばっているか"}]}'::jsonb, null, null, '["中文"]'::jsonb, 8),
  ('n1-chuubun-0008', 'N1', 'chuubun', 'n1-chuubun-g004', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 見るべきだと して いるのは 何か。', null, '["予測した人の経験年数", "予測の言い切り方", "的中した回数", "外れたときの修正と、外れ方の分布"]'::jsonb, 3, '["経験年数の話は出ていない", "言い切る人が得をすることを批判している", "一回の的中とは無関係だと述べている"]'::jsonb, '{"es": "Dos criterios: qué corrige tras fallar, y si sus «setenta por ciento» ocurren en torno al setenta por ciento.", "en": "Two criteria: what he corrects after a miss, and whether his ''seventy per cents'' happen about seventy per cent of the time."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 8),
  ('n1-chuubun-0009', 'N1', 'chuubun', 'n1-chuubun-g004', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '最後の 段落で 筆者が 述べて いることは 何か。', null, '["評価する力のほうが身につきにくい", "予測は誰にもできない", "予測は何度も行うべきだ", "劇的な的中にこそ価値がある"]'::jsonb, 0, '["予測そのものを否定していない", "回数は判断材料の説明として出ただけ", "記憶に残るだけで価値があるとは述べていない"]'::jsonb, '{"es": "Cierra ahí: cuesta más aprender a juzgar predicciones que a hacerlas.", "en": "That''s the closing line: learning to judge forecasts is harder than learning to make them."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 8),
  ('n1-chobun-0001', 'N1', 'chobun', 'n1-chobun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が その 手順を やめたのは、なぜか。', null, '["同じ数字が別の場所に残っていたから", "作業に時間がかかりすぎたから", "監査で不要だと言われたから", "前任者にそう言われたから"]'::jsonb, 0, '["時間の話は出ていない", "監査ではむしろ求められた", "前任者は理由を書き残していない"]'::jsonb, '{"es": "El dato ya estaba en formato electrónico y nadie miraba el papel: le pareció redundante.", "en": "The figure was already stored electronically and nobody looked at the paper: it seemed redundant."}'::jsonb, null, '{"texto": "前任者から引き継いだ仕事に、意味の分からない手順が一つあった。毎週金曜に、ある数字を紙に書き写して保管する。誰も見ない。電子化された同じ数字が、別の場所にきちんと残っている。無駄だと判断して、私はそれをやめた。\n半年後、監査でその紙を求められた。電子の記録は改ざんの可能性を問われることがあり、手書きの控えがあれば説明が早いのだという。前任者は、その理由を引き継ぎ書に書いていなかった。おそらく本人も、誰かから受け取ったときに理由を聞いていない。手順だけが、理由を失ったまま十年以上動いていたことになる。\nこのとき私が学んだのは、無駄に見える手順を残せということではない。理由を書き残さなければ、次の人はそれを消す、ということだ。そして消えたあとで初めて、その手順が何を防いでいたのかが分かる。防いでいたものは、たいてい目に見えない。事故が起きなかった日は、記録に残らないからである。\n厄介なのは、理由のない手順も本当に存在することである。すべてを残していけば、組織はいずれ動かなくなる。だから判断は必要だ。ただ、判断の材料が「意味が分からない」だけでは足りない。分からないのが、こちらの知識不足なのか、相手の思考停止なのかを、区別する手間を惜しんではいけない。この二つは、外から見た形がまったく同じである。\n引き継ぎとは、作業の移動ではなく、判断の履歴の移動である。何をするかではなく、なぜそれを選んだか。書くのに時間はかかるが、書かなければ、次の人は同じ失敗をもう一度やり直すことになる。私が消した紙を、今は毎週書いている。理由も一緒に。", "notas": [{"termino": "改ざん", "glosa": "記録を勝手に書き変えること"}, {"termino": "監査", "glosa": "外から記録を調べること"}]}'::jsonb, null, null, '["長文"]'::jsonb, 7),
  ('n1-chobun-0002', 'N1', 'chobun', 'n1-chobun-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「防いで いた もの」とは、この 場合 どういう ものか。', null, '["紙の保管にかかる費用", "電子記録への疑いに説明できなくなること", "前任者からの苦情", "数字の書き間違い"]'::jsonb, 1, '["費用の話は出ていない", "苦情の話は出ていない", "書き写しの正確さは問題になっていない"]'::jsonb, '{"es": "El papel servía para responder rápido cuando se pone en duda el registro electrónico.", "en": "The paper existed to answer quickly when the electronic record is questioned."}'::jsonb, null, null, null, null, '["長文"]'::jsonb, 8),
  ('n1-chobun-0003', 'N1', 'chobun', 'n1-chobun-g001', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '手順を 消すかどうかの 判断に ついて、筆者は 何が 必要だと 述べて いるか。', null, '["前任者に必ず確認すること", "監査の基準に従うこと", "分からない理由がどちら側にあるかを見分けること", "すべての手順を残すこと"]'::jsonb, 2, '["確認できない場合を前提にしている", "監査は結果として出てきた例", "組織が動かなくなると述べている"]'::jsonb, '{"es": "Hay que distinguir si la opacidad viene de mi ignorancia o de que el otro dejó de pensar.", "en": "You must tell whether the opacity comes from your own ignorance or from the other party having stopped thinking."}'::jsonb, null, null, null, null, '["長文"]'::jsonb, 8),
  ('n1-chobun-0004', 'N1', 'chobun', 'n1-chobun-g001', 3, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考える「引き継ぎ」とは 何か。', null, '["失敗を隠さないこと", "作業を正確に移すこと", "書類を整理すること", "判断の履歴を移すこと"]'::jsonb, 3, '["隠す隠さないの話ではない", "作業の移動ではないと述べている", "整理の話ではない"]'::jsonb, '{"es": "Lo formula así: no se traspasa qué se hace, sino por qué se eligió hacerlo.", "en": "He puts it this way: what''s handed over isn''t what you do, but why it was chosen."}'::jsonb, null, null, null, null, '["長文"]'::jsonb, 8),
  ('n1-tougou-0003', 'N1', 'tougou', 'n1-tougou-g002', 0, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '若手の 育て方に ついて、AとBが 共通して 前提に して いることは 何か。', null, '["失敗はできるだけ避けるべきであること", "支える側の負担が問題であること", "失敗そのものに教育的な価値がありうること", "若手には枠組みが不要であること"]'::jsonb, 2, '["Aは失敗させるべきだと述べている", "どちらも負担については触れていない", "Bは枠組みが先だと述べている"]'::jsonb, '{"es": "B no niega el valor del fallo: dice que hace falta un marco para aprovecharlo. Los dos parten de que el fallo puede enseñar.", "en": "B doesn''t deny failure''s value: it says a framework is needed to use it. Both start from failure being able to teach."}'::jsonb, null, '{"texto": "A\n若手にはまず失敗させるべきである。失敗の記憶は、成功の記憶よりはるかに長く残る。手厚く支えて成功だけを積ませても、支えを外した瞬間に崩れる。転ばせずに歩かせようとする指導は、歩き方ではなく支えられ方を教えているにすぎない。\n\nB\n失敗から学べるのは、失敗の原因を分析できる人だけである。分析の枠組みを持たない段階で失敗させても、残るのは「自分には向いていない」という結論だけだ。それは学習ではなく、単なる撤退である。順序としては、枠組みが先にくる。枠組みさえあれば、失敗は素材になる。", "notas": []}'::jsonb, null, null, '["統合理解"]'::jsonb, 8),
  ('n1-shuchou-0001', 'N1', 'shuchou', 'n1-shuchou-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は 便利な サービスを どう 定義して いるか。', null, '["こちらがしていた動作を誰かが代わりにする仕組み", "選択肢を増やす仕組み", "時間を節約する仕組み", "費用を下げる仕組み"]'::jsonb, 0, '["むしろ触れるものが減ると述べている", "節約は結果であって定義ではない", "費用には触れていない"]'::jsonb, '{"es": "Abre con esa definición: lo que hacíamos nosotros pasa a hacerlo otro.", "en": "It opens with that definition: what we used to do, someone else now does."}'::jsonb, null, '{"texto": "便利なサービスとは、本来こちらがしていたことを、誰かが代わりにするようにした仕組みである。運ぶ、選ぶ、待つ、比べる。これらの動作が私たちの手から離れていく速さは、ここ二十年で著しく上がった。\nこのこと自体を嘆くつもりはない。手放した動作の多くは、実際どうでもよかった。米を研ぐ時間が減って困った人はほとんどいないだろう。問題は、動作と一緒に、その動作が生んでいた情報まで手放してしまう場合があることだ。動作は目に見えるが、情報は見えない。だから、失われても気づかれない。手放してよかったかどうかは、手放してからでないと分からず、しかも比べる相手はもう存在しない。\nたとえば、自分で店を回って買い物をしていたころ、私たちは値段以外のものも見ていた。棚の減り方、店員の顔ぶれ、隣の客が何を手に取ったか。買う気のない商品の情報が、勝手に入ってきていたのである。それらは意識に上らないまま、判断の背景を静かにつくっていたはずだ。何を買わなかったかという記憶さえ、次の判断には効いている。\n代行が進むと、入ってくるのは頼んだものだけになる。効率としては正しい。しかし、頼まなかったものに触れないということは、自分の関心の外側に何があるかを知る機会を失うということでもある。関心の外側は、定義上、自分では要求できない。要求できないものを運んでくる回路が、便利さと引き換えに細くなっていく。検索という行為が象徴的である。検索は、探し方を知っている人にしか使えない。\n誤解を避けたい。昔に戻れという話ではない。私が言いたいのは、便利さを評価するとき、節約できた時間だけを数えるのは片手落ちだということである。何を見なくなったかは、時間のように数えられないので、家計簿にも決算書にも現れない。現れないものは、たいてい過小評価される。数えられる指標だけで意思決定をする組織が、数えられない資産をいつのまにか失っていく理由も、おそらくここにある。\n対策があるとすれば、意図的に非効率な回路を一つ残しておくことくらいだろう。私は本だけは店で買うことにしている。目当ての本の隣に何が置かれているかを見るためである。効率が悪いのは承知のうえだ。悪いからこそ、そこにまだ残っているものがある。", "notas": [{"termino": "代行", "glosa": "本人の代わりに行うこと"}, {"termino": "片手落ち", "glosa": "一方だけを見ていて不十分なこと"}]}'::jsonb, null, null, '["主張理解"]'::jsonb, 8),
  ('n1-shuchou-0002', 'N1', 'shuchou', 'n1-shuchou-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 問題に して いるのは、どういう 場合か。', null, '["店員の数が減ってしまう場合", "動作と一緒に、その動作が生んでいた情報まで手放す場合", "自分でする動作が増えてしまう場合", "費用が予想より高くなる場合"]'::jsonb, 1, '["店員の顔ぶれは例として出ただけ", "動作が減ることを前提にしている", "費用の話はしていない"]'::jsonb, '{"es": "No le molesta ceder el gesto, sino perder con él lo que el gesto traía consigo.", "en": "He doesn''t mind giving up the action, but losing what the action brought along with it."}'::jsonb, null, null, null, null, '["主張理解"]'::jsonb, 8),
  ('n1-shuchou-0003', 'N1', 'shuchou', 'n1-shuchou-g001', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「関心の 外側」に ついて、筆者は どう 述べて いるか。', null, '["努力すれば自分で要求できる", "効率化によってむしろ広がる", "定義上、自分では要求できない", "家計簿に金額として現れる"]'::jsonb, 2, '["要求できないと明記している", "細くなると述べている", "数えられないので現れないと述べている"]'::jsonb, '{"es": "Es la clave del texto: no puedes pedir lo que aún no sabes que existe.", "en": "That''s the hinge of the text: you cannot ask for what you don''t yet know exists."}'::jsonb, null, null, null, null, '["主張理解"]'::jsonb, 9),
  ('n1-shuchou-0004', 'N1', 'shuchou', 'n1-shuchou-g001', 3, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 本だけは 店で 買うのは、なぜか。', null, '["店のほうが値段が安いから", "店員と話したいから", "そのほうが効率がよいから", "目当ての本の隣にあるものを見るため"]'::jsonb, 3, '["値段には触れていない", "店員と話す話は出ていない", "効率が悪いのは承知だと述べている"]'::jsonb, '{"es": "Es su «circuito ineficiente» a propósito: el estante de al lado le trae lo que no pidió.", "en": "It''s his deliberate ''inefficient circuit'': the neighbouring shelf brings him what he didn''t ask for."}'::jsonb, null, null, null, null, '["主張理解"]'::jsonb, 8),
  ('n1-jouhou-0001', 'N1', 'jouhou', 'n1-jouhou-g001', 0, '右のページは、市の助成金の案内である。これを読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '従業員 十人の 飲食店が、店の 入口の 段差を なくす 工事を 九十万円で 行う。助成額は いくらか。', null, '["四十五万円", "五十万円", "三十万円", "八十万円"]'::jsonb, 0, '["五十万円は三分の一の場合の上限", "三分の一は段差を含まない工事の場合", "八十万円は上限であって助成額ではない"]'::jsonb, '{"es": "Al incluir la eliminación del desnivel se aplica la mitad: 90 × 1/2 = 45, por debajo del tope de 80.", "en": "Because it includes step removal, the half rate applies: 90 × 1/2 = 45, under the 80 cap."}'::jsonb, null, '{"texto": "【さくら市　商店リフォーム助成金のご案内】\n\n■ 対象となる方\n　市内で一年以上営業している事業者。ただし、次に当てはまる方は対象外です。\n　・市税を滞納している方\n　・過去三年以内に同じ助成金を受けた方\n　・従業員が二十一人以上の事業者\n\n■ 対象となる工事\n　店舗の外装・内装の改修、看板の設置、段差の解消など。\n　※ 住居部分のみの工事、機械や備品の購入は対象になりません。\n\n■ 助成額\n　工事費の三分の一（上限五十万円）\n　※ 段差の解消を含む工事は、二分の一（上限八十万円）となります。\n\n■ 申請に必要な書類\n　・申請書（市のホームページから入手できます）\n　・工事の見積書（二社以上のものを添えてください）\n　・店舗の現況写真\n　・市税の納税証明書（三か月以内に発行されたもの）\n　※ 見積書は、工事の内容ごとに金額が分かるようにしてください。\n\n■ 申請の流れ\n　1　事前相談（工事の契約前に必ず行ってください）\n　2　申請書の提出（4月1日〜6月30日）\n　3　交付決定通知の受け取り\n　4　工事の開始\n　5　完了報告書の提出（工事完了から三十日以内）\n\n※ 交付決定の前に契約または着工した工事は、対象外となります。\n※ 申請額の合計が予算を超えた場合は、事前相談の受付順で決定します。\n※ 完了報告書の提出が翌年2月末を過ぎる見込みの場合は、あらかじめご連絡ください。\n\n■ お問い合わせ\n　産業振興課　窓口受付は平日の午前八時三十分から午後五時まで。\n　電話でのご相談は、午後一時以降にお願いします。", "notas": [{"termino": "滞納", "glosa": "払うべきものを払っていないこと"}, {"termino": "交付決定", "glosa": "お金を出すと市が正式に決めること"}]}'::jsonb, null, null, '["情報検索"]'::jsonb, 8),
  ('n1-jouhou-0002', 'N1', 'jouhou', 'n1-jouhou-g001', 1, '右のページは、市の助成金の案内である。これを読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', 'この 案内から 分かることは どれか。', null, '["予算を超えた場合は申請書の提出順で決まる", "交付決定の前に工事を始めると対象外になる", "工事の契約後でも事前相談ができる", "機械の購入も助成の対象になる"]'::jsonb, 1, '["事前相談の受付順で決定する", "事前相談は契約前に必ず行う", "機械や備品の購入は対象外"]'::jsonb, '{"es": "La primera nota lo dice: contratar o empezar antes de la resolución deja la obra fuera.", "en": "The first note says it: signing or starting before the decision puts the work out of scope."}'::jsonb, null, null, null, null, '["情報検索"]'::jsonb, 7),
  ('n1-kanji_yomi-0001', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '両者の主張は最後まで<u>隔たり</u>が大きかった。', null, '["へだたり", "かたより", "ひろがり", "つながり"]'::jsonb, 0, '["偏りは別語", "広がりは別語", "繋がりは別語"]'::jsonb, '{"es": "隔たり = へだたり, «distancia, brecha». 偏り (かたより) es «sesgo».", "en": "隔たり = へだたり, ''gap''. 偏り (かたより) is ''bias''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0002', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '担当者の説明はきわめて<u>簡潔</u>だった。', null, '["かんきつ", "かんけつ", "かんげつ", "けんけつ"]'::jsonb, 1, '["促音の誤り", "濁点の誤り", "けんは別字"]'::jsonb, '{"es": "簡潔 = かんけつ, «conciso».", "en": "簡潔 = かんけつ, ''concise''."}'::jsonb, null, null, null, null, '["音読み"]'::jsonb, 3),
  ('n1-kanji_yomi-0003', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼は自らの過ちを<u>潔</u>く認めた。', null, '["すがすが", "いさま", "いさぎよ", "きよ"]'::jsonb, 2, '["清々しいの読み", "存在しない読み", "清いの読み"]'::jsonb, '{"es": "潔い = いさぎよい, «digno, sin excusas». 清い es きよい.", "en": "潔い = いさぎよい, ''clean, without excuses''. 清い is きよい."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-bunmyaku-0001', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '長年の交渉の末、両国はようやく合意に（　）。', null, '["達した", "至った", "及んだ", "届いた"]'::jsonb, 0, '["至るは結果一般で合意には使いにくい", "及ぶは範囲", "届くは物理的"]'::jsonb, '{"es": "合意に達する es la colocación fija. 至る se usa con 結論 o 事態, no tanto con 合意.", "en": "合意に達する is the fixed collocation. 至る goes with 結論 or 事態 rather than 合意."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 4),
  ('n1-bunmyaku-0002', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'その提案は現場の実情を（　）いないと批判された。', null, '["擁して", "踏まえて", "控えて", "据えて"]'::jsonb, 1, '["擁するは抱える", "控えるは差し控える", "据えるは固定する"]'::jsonb, '{"es": "実情を踏まえる = partir de la situación real. Es la colocación esperada.", "en": "実情を踏まえる = to be grounded in the actual situation. It''s the expected collocation."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 4),
  ('n1-iikae-0001', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼の努力は<u>目覚ましい</u>成果をあげた。', null, '["非常にすぐれた", "わずかな", "予想どおりの", "一時的な"]'::jsonb, 0, '["逆の意味", "評価が入っていない", "時間の話ではない"]'::jsonb, '{"es": "目覚ましい = notable, asombroso. Marca un resultado muy por encima de lo normal.", "en": "目覚ましい = remarkable, striking. It marks a result well above the ordinary."}'::jsonb, null, null, null, null, '["形容詞"]'::jsonb, 4),
  ('n1-iikae-0002', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'この件については<u>おおむね</u>合意が得られている。', null, '["ようやく", "だいたい", "まったく", "わずかに"]'::jsonb, 1, '["時間の話ではない", "完全という意味ではない", "少しではない"]'::jsonb, '{"es": "おおむね = en líneas generales, la mayor parte. No es «del todo» ni «apenas».", "en": "おおむね = broadly, for the most part. Not ''entirely'' nor ''barely''."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 3),
  ('n1-youhou-0001', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'のべ', null, '["三日間でのべ千人が来場した。", "この作業はのべ三時間で終わった。", "彼はのべ意見を述べた。", "のべ大きな声で呼んだ。"]'::jsonb, 0, '["実時間には使わない", "副詞ではない", "副詞ではない"]'::jsonb, '{"es": "延べ cuenta el total acumulado sumando días o personas, aunque se repitan. No es «en total de tiempo real».", "en": "延べ counts a cumulative total across days or people, repeats included. It isn''t ''in real elapsed time''."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 4),
  ('n1-youhou-0002', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'を踏まえて', null, '["会場を踏まえて、席を並べた。", "前回の議論を踏まえて、案を作りなおした。", "天気を踏まえて、雨が降った。", "彼を踏まえて、話を聞いた。"]'::jsonb, 1, '["場所には使わない", "結果を導く形になっていない", "人には使わない"]'::jsonb, '{"es": "〜を踏まえて toma algo previo (una discusión, unos datos) como base para lo siguiente.", "en": "〜を踏まえて takes something prior (a discussion, data) as the basis for what follows."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 4),
  ('n1-kanji_yomi-0004', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '事態の悪化を<u>阻</u>むために手を打った。', null, '["ふせ", "のぞ", "こば", "はば"]'::jsonb, 3, '["防ぐの読み", "望むの読み", "拒むの読み"]'::jsonb, '{"es": "阻む = はばむ, «impedir el paso». 拒む (こばむ) es «rechazar».", "en": "阻む = はばむ, ''to block''. 拒む (こばむ) is ''to refuse''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0005', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '新制度の<u>是非</u>をめぐって議論が続いている。', null, '["ぜひ", "しひ", "ぜはい", "これひ"]'::jsonb, 0, '["是をしと読む誤り", "非をはいと読む誤り", "訓読みとの混同"]'::jsonb, '{"es": "是非 = ぜひ, aquí «lo acertado y lo desacertado», no el adverbio «por favor».", "en": "是非 = ぜひ, here ''the rights and wrongs'', not the adverb ''by all means''."}'::jsonb, null, null, null, null, '["音読み"]'::jsonb, 4),
  ('n1-kanji_yomi-0006', 'N1', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼の功績は<u>著</u>しく評価が高い。', null, '["めざま", "いちじる", "あらわ", "はなは"]'::jsonb, 1, '["目覚ましいの読み", "著すの別の読み", "甚だしいの読み"]'::jsonb, '{"es": "著しい = いちじるしい. El mismo kanji leído あらわ- es 著す «escribir (una obra)».", "en": "著しい = いちじるしい. The same kanji read あらわ- gives 著す ''to author''."}'::jsonb, null, null, null, null, '["訓読み"]'::jsonb, 5),
  ('n1-bunmyaku-0003', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この分野の研究は、まだ（　）の段階にある。', null, '["探検", "詮索", "模索", "思索"]'::jsonb, 2, '["探検は場所", "詮索は他人のことを調べる", "思索は静かに考える"]'::jsonb, '{"es": "模索 = ir a tientas buscando el método. 詮索 es «fisgar» y 思索 «meditar».", "en": "模索 = groping for a method. 詮索 is ''prying'' and 思索 ''contemplation''."}'::jsonb, null, null, null, null, '["語彙"]'::jsonb, 5),
  ('n1-bunmyaku-0004', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '担当者の（　）な対応のおかげで、混乱せずにすんだ。', null, '["的中", "確実", "正確", "的確"]'::jsonb, 3, '["的中は予想が当たる", "確実は間違いない", "正確は数値のずれ"]'::jsonb, '{"es": "的確 = certero, ajustado a la situación. 正確 mide exactitud, no oportunidad.", "en": "的確 = apt, fitting the situation. 正確 measures accuracy, not aptness."}'::jsonb, null, null, null, null, '["語彙"]'::jsonb, 5),
  ('n1-bunmyaku-0005', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '証拠がそろわないうちは、結論を（　）べきだ。', null, '["控える", "抑える", "押さえる", "備える"]'::jsonb, 0, '["抑えるは感情や力", "押さえるは物理的", "備えるは準備"]'::jsonb, '{"es": "結論を控える = abstenerse de concluir. 抑える va con 感情 o costes.", "en": "結論を控える = to refrain from concluding. 抑える goes with emotions or costs."}'::jsonb, null, null, null, null, '["コロケーション"]'::jsonb, 5),
  ('n1-iikae-0003', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'その報告には<u>一抹</u>の不安が残る。', null, '["大きな", "明らかな", "わずかな", "確かな"]'::jsonb, 2, '["程度が逆", "明白さの話ではない", "確実さの話ではない"]'::jsonb, '{"es": "一抹の = una pizca de. Marca una cantidad mínima, no una grande.", "en": "一抹の = a trace of. It marks a minimal amount, not a large one."}'::jsonb, null, null, null, null, '["連体"]'::jsonb, 5),
  ('n1-iikae-0004', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼は<u>おのずから</u>答えにたどり着いた。', null, '["人に聞いて", "偶然に", "急いで", "自然に"]'::jsonb, 3, '["他人は関わらない", "偶然とはちがう", "速さの話ではない"]'::jsonb, '{"es": "おのずから = por sí solo, de forma natural. No es azar ni prisa.", "en": "おのずから = of itself, naturally. Not chance and not haste."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 5),
  ('n1-iikae-0005', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼の話には<u>とりとめ</u>がない。', null, '["まとまりがない", "おもしろみがない", "根拠がない", "遠慮がない"]'::jsonb, 0, '["面白さの話ではない", "根拠の話ではない", "態度の話ではない"]'::jsonb, '{"es": "とりとめがない = deshilvanado, sin hilo. No es que sea falso ni aburrido.", "en": "とりとめがない = rambling, without a thread. Not false and not boring."}'::jsonb, null, null, null, null, '["慣用"]'::jsonb, 5),
  ('n1-youhou-0003', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '目安', null, '["彼を目安にして歩いた。", "目安を立てて席に着いた。", "完成の目安は来月末です。", "この本は目安が高い。"]'::jsonb, 2, '["目印の誤用", "目標の誤用", "値段の誤用"]'::jsonb, '{"es": "目安 = referencia aproximada de cantidad o plazo. Para orientarse por un punto es 目印.", "en": "目安 = a rough guide for an amount or a date. To navigate by a point you''d use 目印."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 5),
  ('n1-youhou-0004', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '打開', null, '["窓を打開して風を入れた。", "古い建物を打開して新しくした。", "彼の意見を打開して認めた。", "行きづまった状況を打開したい。"]'::jsonb, 3, '["開けるの誤用", "取り壊すの誤用", "撤回するの誤用"]'::jsonb, '{"es": "打開 = desbloquear una situación estancada. No se aplica a objetos ni a ventanas.", "en": "打開 = to break a deadlock. It doesn''t apply to objects or windows."}'::jsonb, null, null, null, null, '["用法"]'::jsonb, 5),
  ('n1-bunmyaku-0006', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '十年に及ぶ交渉が、ようやく（　）を見た。', null, '["決裂", "決着", "決意", "決断"]'::jsonb, 1, '["物別れに終わることを指す", "自分が心を決めること", "自分が心を決めること"]'::jsonb, '{"es": "決着を見る = quedar zanjado. 決裂 es lo contrario, y 決断・決意 son actos de una sola parte.", "en": "決着を見る = to be settled. 決裂 is the opposite, and 決断/決意 are one-sided acts of will."}'::jsonb, null, null, null, null, '[]'::jsonb, 6),
  ('n1-bunmyaku-0007', 'N1', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の主張は最初と最後で食い違っており、（　）を欠いている。', null, '["客観性", "独創性", "一貫性", "具体性"]'::jsonb, 2, '["立場の偏りの問題ではない", "新しさの問題ではない", "細かさの問題ではない"]'::jsonb, '{"es": "Que el principio y el final se contradigan es falta de 一貫性, de coherencia.", "en": "Beginning and end contradicting each other is a lack of 一貫性 — consistency."}'::jsonb, null, null, null, null, '[]'::jsonb, 6),
  ('n1-iikae-0006', 'N1', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼は<u>やむを得ず</u>その案を受け入れた。', null, '["ひそかに", "しかたなく", "ただちに", "喜んで"]'::jsonb, 1, '["人に知られないようにという意味", "すぐという意味", "気持ちが逆になる"]'::jsonb, '{"es": "やむを得ず = sin más remedio. No hay voluntad detrás, sólo ausencia de alternativa.", "en": "やむを得ず = having no choice. There''s no willingness behind it, just no alternative."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 6),
  ('n1-youhou-0005', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'もっぱら', null, '["彼は最近もっぱら研究に打ち込んでいる。", "この道はもっぱら広い。", "もっぱら雨が降り出した。", "彼女にはもっぱら三人の子どもがいる。"]'::jsonb, 0, '["程度を表す語ではない", "出来事の始まりには使わない", "数を限る語ではない"]'::jsonb, '{"es": "もっぱら marca dedicación exclusiva a una actividad, no grado ni cantidad.", "en": "もっぱら marks exclusive devotion to an activity, not degree or quantity."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 6),
  ('n1-youhou-0006', 'N1', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'かねて', null, '["彼はかねて背が高い。", "かねてより計画していた旅行に出た。", "この本はかねて面白い。", "かねて雨が激しくなった。"]'::jsonb, 1, '["程度を表す語ではない", "程度を表す語ではない", "変化の始まりには使わない"]'::jsonb, '{"es": "かねて（より）= de antes, desde hace tiempo. Acompaña a lo que venía preparándose.", "en": "かねて(より) = beforehand, for some time. It goes with what had been building up."}'::jsonb, null, null, null, null, '["副詞"]'::jsonb, 6),
  ('n2-bunpou1-0001', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は仕事が忙しい（　）、会議には必ず出席する。', null, '["ものの", "ために", "おかげで", "ばかりに"]'::jsonb, 0, '["ためには理由", "おかげでは good cause", "ばかりにはbad cause"]'::jsonb, '{"es": "〜ものの = «aunque», concesivo. Los otros tres son de causa, y aquí no hay causa sino contraste.", "en": "〜ものの = ''although'', concessive. The other three mark cause, but this sentence contrasts rather than explains."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0002', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '一度引き受けた（　）、最後までやり遂げるつもりだ。', null, '["とはいえ", "からには", "ところで", "どころか"]'::jsonb, 1, '["とはいえは逆接", "ところでは逆接", "どころかは否定強調"]'::jsonb, '{"es": "〜からには = «ya que…, entonces por fuerza». Introduce la determinación que sigue.", "en": "〜からには = ''now that…, then of course''. It sets up the resolve that follows."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0003', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '今さら先生に言われた（　）、勉強する気にはなれない。', null, '["とともに", "からこそ", "ところで", "ばかりに"]'::jsonb, 2, '["とともには同時", "からこそは肯定的理由", "ばかりにはbad cause"]'::jsonb, '{"es": "〜たところで = «aunque me lo digan, da igual». Siempre lleva un resultado negativo o inútil.", "en": "〜たところで = ''even if they tell me, it won''t help''. It always leads to a futile or negative result."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0004', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の実力（　）、優勝は当然の結果と言える。', null, '["どころか", "において", "にしては", "からすれば"]'::jsonb, 3, '["どころかは否定強調", "においては場面", "にしてはは期待外れ"]'::jsonb, '{"es": "〜からすれば = «a juzgar por». にしては diría lo contrario: que el resultado no cuadra con su nivel.", "en": "〜からすれば = ''judging from''. にしては would say the opposite: that the result doesn''t match his level."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0005', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '体調が悪いので、今回の出張は見送らざる（　）。', null, '["を得ない", "にすぎない", "ようがない", "ほかならない"]'::jsonb, 0, '["にすぎないは程度", "ようがないは手段の不在", "ほかならないは断定"]'::jsonb, '{"es": "〜ざるを得ない = «no queda más remedio que». Se une a la forma ない sin el ない: 見送らざるを得ない.", "en": "〜ざるを得ない = ''have no choice but to''. It attaches to the ない-stem: 見送らざるを得ない."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0006', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は忙しい忙しいと言い（　）、毎晩飲みに行っている。', null, '["ばかり", "つつ", "がち", "きり"]'::jsonb, 1, '["ばかりは限定", "がちは傾向", "きりは以来"]'::jsonb, '{"es": "〜つつ = «mientras dice…, en realidad». Marca contradicción entre lo que se dice y lo que se hace.", "en": "〜つつ = ''while saying…, actually''. It marks the gap between what is said and what is done."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0007', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'あの店は値段が高い（　）、味は確かだ。', null, '["どころか", "にしては", "だけあって", "ばかりか"]'::jsonb, 2, '["どころかは否定強調", "にしてはは期待外れ", "ばかりかは追加"]'::jsonb, '{"es": "〜だけあって = «como corresponde a lo caro que es». El precio justifica la calidad.", "en": "〜だけあって = ''as befits how expensive it is''. The price justifies the quality."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0008', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '連絡先が分からないので、知らせ（　）がない。', null, '["もの", "ところ", "こと", "よう"]'::jsonb, 3, '["ものは物事", "ところは場所や場面", "ことは事柄"]'::jsonb, '{"es": "〜ようがない = «no hay manera de». Se forma con la raíz masu: 知らせ＋ようがない.", "en": "〜ようがない = ''there''s no way to''. Built on the masu-stem: 知らせ＋ようがない."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0009', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '小学生（　）、ずいぶん難しい言葉を知っているね。', null, '["にしては", "としては", "にしても", "において"]'::jsonb, 0, '["としてはは立場", "にしてもは譲歩", "においては場面"]'::jsonb, '{"es": "〜にしては = «para ser…, sorprende». Marca que la realidad no cuadra con lo esperado de esa categoría.", "en": "〜にしては = ''for a…, surprisingly''. It flags that reality doesn''t match what the category leads you to expect."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0010', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '試験に受かるかどうかは、これからの努力（　）だ。', null, '["きり", "次第", "まま", "ばかり"]'::jsonb, 1, '["きりは以来", "ままは状態の維持", "ばかりは限定"]'::jsonb, '{"es": "〜次第だ = «depende de». Lo que va delante decide el resultado.", "en": "〜次第だ = ''depends on''. What comes before decides the outcome."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0011', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '準備が終わらない（　）、始めるわけにはいかない。', null, '["ものなら", "どころか", "ことには", "かぎりで"]'::jsonb, 2, '["ものならは仮定", "どころかは否定強調", "かぎりでは範囲"]'::jsonb, '{"es": "〜ないことには = «si no…, entonces no». Condición imprescindible, siempre en negativo.", "en": "〜ないことには = ''unless…, then not''. An indispensable condition, always negative."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0012', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この本は読めば読む（　）、面白くなってくる。', null, '["きり", "だけ", "まま", "ほど"]'::jsonb, 3, '["きりは以来", "だけは限定", "ままは維持"]'::jsonb, '{"es": "〜ば〜ほど = «cuanto más…, más». La estructura pide 読めば読むほど.", "en": "〜ば〜ほど = ''the more…, the more''. The pattern requires 読めば読むほど."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou2-0001', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'この計画は ＿＿ ＿★＿ ＿＿ ＿＿ 中止になった。', '住民 の 反対 により', '["の", "反対", "住民", "により"]'::jsonb, 0, '[]'::jsonb, '{"es": "Orden: 住民 の 反対 により. La estrella está en la casilla 2, donde va 「の」.", "en": "Order: 住民 の 反対 により. The star is in slot 2, which takes 「の」."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0002', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '彼は ＿＿ ＿★＿ ＿＿ ＿＿ 諦めなかった。', '何度 も 失敗したの に', '["に", "も", "何度", "失敗したの"]'::jsonb, 1, '[]'::jsonb, '{"es": "Orden: 何度 も 失敗したの に. La estrella está en la casilla 2, donde va 「も」.", "en": "Order: 何度 も 失敗したの に. The star is in slot 2, which takes 「も」."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0003', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '日本語は ＿＿ ＿★＿ ＿＿ ＿＿ 難しくなる。', '勉強 すれば する ほど', '["ほど", "勉強", "すれば", "する"]'::jsonb, 2, '[]'::jsonb, '{"es": "Orden: 勉強 すれば する ほど. La estrella está en la casilla 2, donde va 「すれば」.", "en": "Order: 勉強 すれば する ほど. The star is in slot 2, which takes 「すれば」."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0004', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '先生の ＿＿ ＿★＿ ＿＿ ＿＿ 合格できた。', '助言 の おかげ で', '["おかげ", "で", "助言", "の"]'::jsonb, 3, '[]'::jsonb, '{"es": "Orden: 助言 の おかげ で. La estrella está en la casilla 2, donde va 「の」.", "en": "Order: 助言 の おかげ で. The star is in slot 2, which takes 「の」."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0005', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'あの店は ＿＿ ＿★＿ ＿＿ ＿＿ 味がいい。', '値段が 高い だけ あって', '["高い", "あって", "だけ", "値段が"]'::jsonb, 0, '[]'::jsonb, '{"es": "Orden: 値段が 高い だけ あって. La estrella está en la casilla 2, donde va 「高い」.", "en": "Order: 値段が 高い だけ あって. The star is in slot 2, which takes 「高い」."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-youhou-0005', 'N2', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'そなえる', null, '["地震にそなえて水を用意しておく。", "彼は毎朝、新聞をそなえて読む。", "この機械は音がそなえて動く。", "田中さんは背がそなえて高い。"]'::jsonb, 0, '["読み方の説明にならない", "機械の動作には使わない", "程度を表す語ではない"]'::jsonb, '{"es": "備える es prepararse ante algo que puede venir: un terremoto, una emergencia.", "en": "備える is to prepare for something that may come: an earthquake, an emergency."}'::jsonb, null, null, null, null, '[]'::jsonb, 4),
  ('n2-bunshou_bunpou-0001', 'N2', 'bunshou_bunpou', 'n2-bb-g001', 0, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　1　）', null, '["わけではない", "にちがいない", "ほかならない", "しかない"]'::jsonb, 0, '["強い断定になり、後ろの説明と合わない", "断定を強める言い方", "選択肢がないという意味になる"]'::jsonb, '{"es": "Niega parcialmente el dicho: «no es que se aprenda automáticamente». Eso es 〜わけではない.", "en": "It partly denies the saying: ''it''s not that you automatically learn''. That''s 〜わけではない."}'::jsonb, null, '{"texto": "「失敗から学べ」とよく言われる。だが、失敗すれば自動的に何かを学べる（　1　）。同じ失敗を何度もくり返す人は、学んでいないのではなく、振り返る時間を持っていないだけのことが多い。\n振り返りには、事実と解釈を分ける作業が要る。「準備が足りなかった」は解釈であって、事実ではない。事実は「三日前に着手した」「資料を二度書き直した」といった、数えられる形をしている。（　2　）、次に何を変えるかが決まらない。\nもっとも、振り返りが常に有効（　3　）。うまくいかなかった直後は、感情が判断をゆがめる。少し時間を置いてからのほうが、同じできごとでも見え方が変わる。\n失敗を財産に変えるのは、失敗そのものではない。（　4　）である。そしてそれは、意欲ではなく手順の問題だ。手順にしてしまえば、（　5　）人でも続けられる。", "notas": [{"termino": "振り返る", "glosa": "終わったことを見直す"}]}'::jsonb, null, null, '["文章の文法"]'::jsonb, 5),
  ('n2-bunshou_bunpou-0002', 'N2', 'bunshou_bunpou', 'n2-bb-g001', 1, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　2　）', null, '["解釈を重ねるほど", "事実に戻らないかぎり", "時間さえあれば", "事実が多すぎると"]'::jsonb, 1, '["解釈を増やしても決まらないので後ろと合わない", "時間の問題として述べていない", "量の問題として述べていない"]'::jsonb, '{"es": "El párrafo separa hecho e interpretación: sin volver al hecho contable, no se decide qué cambiar.", "en": "The paragraph separates fact from interpretation: without going back to countable facts, you can''t decide what to change."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n2-bunshou_bunpou-0003', 'N2', 'bunshou_bunpou', 'n2-bb-g001', 2, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　3　）', null, '["であるべきだ", "であるとしか思えない", "であるとはかぎらない", "でなければならない"]'::jsonb, 2, '["義務の言い方", "直後に限界を述べているので断定と合わない", "義務の言い方"]'::jsonb, '{"es": "«もっとも» anuncia una salvedad: no siempre sirve. Eso pide 〜とはかぎらない.", "en": "«もっとも» flags a caveat: it isn''t always useful. That calls for 〜とはかぎらない."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n2-bunshou_bunpou-0004', 'N2', 'bunshou_bunpou', 'n2-bb-g001', 3, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　4　）', null, '["失敗の大きさ", "強い意欲", "周りからの助言", "その後の振り返り"]'::jsonb, 3, '["大きさの話は出ていない", "意欲ではないと直後に書いてある", "助言の話は出ていない"]'::jsonb, '{"es": "El texto entero defiende que lo que convierte el fallo en aprendizaje es revisarlo después.", "en": "The whole text argues that what turns failure into learning is reviewing it afterwards."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n2-bunshou_bunpou-0005', 'N2', 'bunshou_bunpou', 'n2-bb-g001', 4, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　5　）', null, '["意志の強くない", "才能のある", "失敗をしない", "時間の余っている"]'::jsonb, 0, '["才能の話は出ていない", "失敗を前提にした文章である", "時間の話は前段の別の論点"]'::jsonb, '{"es": "Si es cuestión de procedimiento y no de ánimo, lo puede sostener quien no tiene voluntad de hierro.", "en": "If it''s a matter of procedure rather than drive, someone without strong willpower can keep it up."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 5),
  ('n2-sokuji-0001', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この資料、明日までにお願いできますか。', null, '["はい、承知しました。", "はい、お願いします。", "いいえ、けっこうです。"]'::jsonb, 0, '["依頼を受けた側が「お願いします」とは言わない", "断り方として不自然"]'::jsonb, '{"es": "Te están pidiendo algo: se acepta con 承知しました. Decir お願いします sería devolverle el encargo.", "en": "You''re being asked to do something: accept with 承知しました. Saying お願いします would hand the job back."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "この資料、明日までにお願いできますか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0002', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '今日はごちそうさまでした。', null, '["いただきます。", "お粗末さまでした。", "ごちそうさまです。"]'::jsonb, 1, '["食べる前の挨拶", "相手の言葉をそのまま返している"]'::jsonb, '{"es": "Quien ha invitado responde お粗末さまでした. いただきます se dice antes de comer.", "en": "The host replies お粗末さまでした. いただきます is said before eating, not after."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "今日はごちそうさまでした。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0003', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '会議、そろそろ始めてもよろしいでしょうか。', null, '["いいえ、始めません。", "ええ、始めました。", "ええ、どうぞ。"]'::jsonb, 2, '["主語がずれている", "許可を求められているのに過去形"]'::jsonb, '{"es": "Piden permiso, así que se concede con どうぞ. 始めました contestaría a otra pregunta.", "en": "They''re asking permission, so grant it with どうぞ. 始めました would answer a different question."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "会議、そろそろ始めてもよろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0004', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'その件でしたら、私がやっておきましょうか。', null, '["では、お願いできますか。", "では、やっておきました。", "では、やらないでください。"]'::jsonb, 0, '["申し出に過去形で答えている", "申し出を断る理由がない"]'::jsonb, '{"es": "Se están ofreciendo: se acepta con お願いできますか.", "en": "They''re offering to help: accept with お願いできますか."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "その件でしたら、私がやっておきましょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0005', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '田中さん、なんだか顔色がよくないですね。', null, '["ええ、色を変えました。", "ええ、ちょっと寝不足で。", "ええ、よく見えます。"]'::jsonb, 1, '["顔色を文字通りの「色」と取った", "意味が通らない"]'::jsonb, '{"es": "顔色がよくない = tienes mala cara. La opción 2 entiende 色 literalmente como un color.", "en": "顔色がよくない = you look unwell. Option 2 takes 色 literally as a colour."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "田中さん、なんだか顔色がよくないですね。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0006', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'すみません、道に迷ってしまって。', null, '["じゃあ、道を作りましょうか。", "じゃあ、迷ってください。", "じゃあ、迎えに行きましょうか。"]'::jsonb, 2, '["文字通りすぎる", "命令として意味が通らない"]'::jsonb, '{"es": "Se ha perdido: lo natural es ofrecerse a ir a buscarlo.", "en": "They''re lost: the natural reply is to offer to come and get them."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "すみません、道に迷ってしまって。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0007', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '部長は、もう帰られましたか。', null, '["ええ、さっき出られましたよ。", "ええ、もうすぐ来られます。", "ええ、帰ってきました。"]'::jsonb, 0, '["時間の向きが逆", "主語がずれている"]'::jsonb, '{"es": "帰られましたか es honorífico: «¿ya se ha ido?». La 2 dice que está por llegar, lo contrario.", "en": "帰られましたか is honorific: ''has he left yet?''. Option 2 says he''s about to arrive — the opposite."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "部長は、もう帰られましたか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0008', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '明日の打ち合わせ、少し遅れるかもしれません。', null, '["では、遅れないでください。", "では、お先に始めておきますね。", "では、早く来てくださいね。"]'::jsonb, 1, '["責める返事になっている", "avisar no es pedir permiso"]'::jsonb, '{"es": "Avisan de que llegarán tarde: se responde adaptándose, no regañando.", "en": "They''re warning they''ll be late: you respond by adapting, not by scolding."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "明日の打ち合わせ、少し遅れるかもしれません。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0009', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'これ、ちょっと味見してみてくれない?', null, '["うん、見るだけね。", "うん、作っておくね。", "うん、ちょっともらうね。"]'::jsonb, 2, '["味見の「見」を文字通りに取った", "頼まれていないこと"]'::jsonb, '{"es": "味見する = probar, no mirar. La 2 se queda en el 見 literal.", "en": "味見する = to taste, not to look. Option 2 gets stuck on the literal 見."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "これ、ちょっと味見してみてくれない?"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0010', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'エアコンをつけてもかまいませんか。', null, '["ええ、どうぞ。", "いいえ、つけました。", "ええ、かまいます。"]'::jsonb, 0, '["否定と過去が矛盾", "かまいませんの肯定形は使わない"]'::jsonb, '{"es": "A 〜てもかまいませんか se contesta どうぞ. «かまいます» no se usa como respuesta afirmativa.", "en": "To 〜てもかまいませんか you answer どうぞ. ''かまいます'' isn''t used as an affirmative reply."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "エアコンをつけてもかまいませんか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0011', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '山田さん、この漢字の読み方、分かる?', null, '["うーん、書いてあるよ。", "うーん、ちょっと自信ないな。", "うーん、読んでおいたよ。"]'::jsonb, 1, '["質問に答えていない", "質問に答えていない"]'::jsonb, '{"es": "Preguntan si lo sabe: se admite la duda. Las otras dos hablan de otra cosa.", "en": "They ask whether you know it: admit the doubt. The other two talk about something else."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "山田さん、この漢字の読み方、分かる?"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0012', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '先週の出張、どうでしたか。', null, '["来週の予定です。", "はい、行ってきます。", "思ったより収穫がありました。"]'::jsonb, 2, '["時期が違う", "これから行く言い方"]'::jsonb, '{"es": "Preguntan por un viaje ya hecho. 行ってきます es para irse ahora y 来週 cambia la fecha.", "en": "They ask about a trip already made. 行ってきます is for leaving now, and 来週 changes the date."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "先週の出張、どうでしたか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-kadai-0001', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の人はこの後まず何をしますか。', null, '["会議室の予約を延長する", "資料を追加で印刷する", "部長に内容を確認する", "参加者に連絡する"]'::jsonb, 0, '["印刷は確認の後", "部長は今いない", "連絡は話に出ていない"]'::jsonb, '{"es": "Hacen falta más copias, pero antes el jefe quiere corregir algo — y ahora está reunido. Lo único que puede hacer ya es ampliar la reserva de la sala.", "en": "More copies are needed, but the boss wants to change something first — and he''s in a meeting. The only thing left to do right now is extend the room booking."}'::jsonb, '["部数が足りない → hay que imprimir más", "その前に部長が直したい → imprimir va después de la revisión", "さっき会議室に入った → ahora no se le puede preguntar", "それまでに予約を延長して → esto es lo inmediato"]'::jsonb, null, '{"intro": "男の人と女の人が会社で話しています。男の人はこの後まず何をしますか。", "turnos": [{"quien": "F", "texto": "田中さん、明日の会議の資料、もうできてる?"}, {"quien": "M", "texto": "はい、印刷もしておきました。"}, {"quien": "F", "texto": "ああ、ちょっと待って。参加者が二人増えたから、部数が足りないかも。"}, {"quien": "M", "texto": "じゃあ、追加で印刷しますね。"}, {"quien": "F", "texto": "うん。でも、その前に部長が内容を一か所直したいって言ってたから、確認してから印刷して。"}, {"quien": "M", "texto": "わかりました。部長、今いらっしゃいますか。"}, {"quien": "F", "texto": "さっき会議室に入ったから、終わるまで待ったほうがいいわ。それまでに会議室の予約を延長しておいてくれる?"}, {"quien": "M", "texto": "はい。"}], "pregunta": "男の人はこの後まず何をしますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "職場"]'::jsonb, 3),
  ('n2-kadai-0002', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人はこれから何を買いますか。', null, '["絵の具とノート", "ノートと鉛筆", "鉛筆と筆", "筆とノート"]'::jsonb, 1, '["絵の具は持っている", "筆は先生が貸してくれる", "筆は借りられる"]'::jsonb, '{"es": "Se van descartando: las pinturas ya las tiene, los pinceles los presta el profesor. Quedan el cuaderno y un lápiz blando.", "en": "Things get ruled out one by one: she already has the paints, the teacher lends the brushes. That leaves the notebook and a soft pencil."}'::jsonb, '["絵の具は去年のがある → no hay que comprarlas", "筆は先生が貸してくれる → tampoco", "ノートは新しいのが要る → sí", "鉛筆は柔らかいのを → sí"]'::jsonb, null, '{"intro": "女の人と男の人が話しています。女の人はこれから何を買いますか。", "turnos": [{"quien": "F", "texto": "来週から絵の教室に通うんだけど、何を用意したらいいかな。"}, {"quien": "M", "texto": "絵の具は持ってる?"}, {"quien": "F", "texto": "うん、去年買ったのがまだ残ってる。"}, {"quien": "M", "texto": "じゃあ大丈夫。筆は最初の授業で先生が貸してくれるはずだよ。"}, {"quien": "F", "texto": "そうなんだ。じゃあ、あとはノートくらいかな。"}, {"quien": "M", "texto": "うん、それと鉛筆。下書きに使うから、柔らかいのを一本ね。"}, {"quien": "F", "texto": "分かった、その二つを買っておく。"}], "pregunta": "女の人はこれから何を買いますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "買い物"]'::jsonb, 3),
  ('n2-kadai-0003', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人は この後 まず 何を しますか。', null, '["会場を予約し直す", "資料を追加で印刷する", "参加者に会場の変更を知らせる", "参加者の数を数える"]'::jsonb, 2, '["会場の変更はもう決まっている", "印刷は後でいいと言われた", "人数はもう分かっている"]'::jsonb, '{"es": "El aviso del cambio de sala tiene que salir hoy; la impresión puede esperar.", "en": "The room-change notice has to go out today; the printing can wait."}'::jsonb, '["参加者が百二十人に増えた", "印刷は後でいい", "会場変更の連絡は今日中"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 話して います。女の人は この後 まず 何を しますか。", "turnos": [{"quien": "M", "texto": "来週の説明会、資料の印刷は終わった?"}, {"quien": "F", "texto": "はい、百部刷りました。"}, {"quien": "M", "texto": "あ、参加者が増えて百二十人になったんだ。"}, {"quien": "F", "texto": "では、追加で刷ります。"}, {"quien": "M", "texto": "いや、印刷は後でいい。それより、会場が変更になったから、参加者に連絡してもらえる? 今日中じゃないと間に合わない。"}, {"quien": "F", "texto": "分かりました。すぐ知らせます。"}], "pregunta": "女の人はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 5),
  ('n2-kadai-0004', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の人は まず 何を しなければ なりませんか。', null, '["業者に頼む", "荷物をまとめる", "契約書を読み直す", "大家に知らせる"]'::jsonb, 3, '["早めがいいが期限があるのは通知のほう", "急ぐ順番としては後", "契約の内容はもう確認できている"]'::jsonb, '{"es": "El contrato pide avisar con un mes, y hoy es justo el límite.", "en": "The contract requires a month''s notice, and today is exactly the deadline."}'::jsonb, '["契約では一か月前まで", "今日がちょうど一か月前", "業者は早めだが期限はない"]'::jsonb, null, '{"intro": "男の人と 女の人が 話して います。男の人は まず 何を しなければ なりませんか。", "turnos": [{"quien": "F", "texto": "引っ越し、来月だっけ。"}, {"quien": "M", "texto": "うん。荷物をまとめて、業者に頼んで。"}, {"quien": "F", "texto": "業者は早めに押さえたほうがいいよ。三月は混むから。"}, {"quien": "M", "texto": "そうだね。でも、その前に大家さんに知らせないと。契約では一か月前までって書いてあった。"}, {"quien": "F", "texto": "今日でちょうど一か月前じゃない?"}, {"quien": "M", "texto": "あ、本当だ。"}], "pregunta": "男の人はまず何をしなければなりませんか。"}'::jsonb, null, '["課題理解"]'::jsonb, 5),
  ('n2-kadai-0005', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '客は この後 まず 何を しますか。', null, '["買った日付を確認する", "商品を交換してもらう", "代わりの品を借りる", "修理を頼む"]'::jsonb, 0, '["日付が分からないと決まらない", "貸出はしていないと言われた", "一年以内なら交換になる可能性がある"]'::jsonb, '{"es": "Todo depende de si han pasado menos de doce meses, y eso lo dice el tique.", "en": "Everything hinges on whether it''s under a year, and the receipt is what says so."}'::jsonb, '["修理は一か月かかる", "貸出はしていない", "一年以内なら交換の可能性"]'::jsonb, null, '{"intro": "店で 店員と 客が 話して います。客は この後 まず 何を しますか。", "turnos": [{"quien": "F", "texto": "こちらの商品、修理は承れますが、一か月ほどかかります。"}, {"quien": "M", "texto": "一か月ですか。代わりの品を借りることはできますか。"}, {"quien": "F", "texto": "貸出はしておりません。ただ、ご購入から一年以内でしたら、交換になる場合がございます。"}, {"quien": "M", "texto": "一年以内かどうか、買ったときの紙を見ないと分からないな。"}, {"quien": "F", "texto": "では、まずご確認いただけますか。日付が分かれば、その場で決められます。"}], "pregunta": "客はこの後まず何をしますか。"}'::jsonb, null, '["課題理解"]'::jsonb, 5),
  ('n2-point-0001', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は どうして 会社を 辞めますか。', null, '["仕事が変わらないから", "人間関係が悪いから", "給料が低いから", "会社が遠いから"]'::jsonb, 0, '["みんないい人だったと言っている", "むしろよかったと言っている", "話に出ていない"]'::jsonb, '{"es": "Cinco años haciendo lo mismo, y la proyección a diez le decide.", "en": "Five years doing the same thing, and picturing ten more decides it."}'::jsonb, '["給料はむしろよかった", "人間関係も悪くない", "去年と同じ仕事を今年もしている"]'::jsonb, null, '{"intro": "男の人と 女の人が 話して います。女の人は どうして 会社を 辞めますか。", "turnos": [{"quien": "M", "texto": "辞めるって聞いたけど、給料の問題?"}, {"quien": "F", "texto": "それはむしろよかったくらい。"}, {"quien": "M", "texto": "じゃあ、人間関係?"}, {"quien": "F", "texto": "みんないい人だったよ。ただ、五年いて、去年と同じ仕事を今年もしていることに気づいて。このままだと十年後も同じだなと思ったの。"}], "pregunta": "女の人はどうして会社を辞めますか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 5),
  ('n2-point-0002', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は この本の どこが いいと 言って いますか。', null, '["内容が新しいこと", "途中から読み直せること", "値段が安いこと", "全体が短いこと"]'::jsonb, 1, '["特に新しくないと言っている", "話に出ていない", "話に出ていない"]'::jsonb, '{"es": "Su mérito no es el contenido sino la estructura: se puede retomar por cualquier punto.", "en": "Its merit isn''t the content but the structure: you can pick it up anywhere."}'::jsonb, '["内容は特に新しくない", "似た本は何冊もある", "どこから再開しても分かる"]'::jsonb, null, '{"intro": "男の人が 本に ついて 話して います。男の人は この本の どこが いいと 言って いますか。", "turnos": [{"quien": "M", "texto": "この本、内容は特に新しくありません。似た本は何冊もあります。ただ、途中で読むのをやめても、どこから再開しても分かるように書いてあるんです。忙しい人が最後まで読める本というのは、案外少ないですから。"}], "pregunta": "男の人はこの本のどこがいいと言っていますか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 5),
  ('n2-point-0003', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何を 心配して いますか。', null, '["作業時間が長いこと", "研修をしていないこと", "分からないときに聞ける相手がいないこと", "評判が悪いこと"]'::jsonb, 2, '["半分になったと言っている", "研修はしたと言っている", "評判はいいと言っている"]'::jsonb, '{"es": "La formación ya se dio; el hueco está en el día a día, cuando alguien se atasca.", "en": "The training happened; the gap is day to day, when someone gets stuck."}'::jsonb, '["作業時間は半分になった", "研修は実施済み", "聞ける相手がいない"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 話して います。女の人は 何を 心配して いますか。", "turnos": [{"quien": "M", "texto": "新しいやり方、評判いいですよ。作業時間が半分になったって。"}, {"quien": "F", "texto": "そうなんです。ただ、慣れている人しか使えていなくて。"}, {"quien": "M", "texto": "研修をすればいいのでは。"}, {"quien": "F", "texto": "研修はしました。問題は、分からなくなったときに聞ける相手がいないことなんです。"}], "pregunta": "女の人は何を心配していますか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 5),
  ('n2-point-0004', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は どうして その 仕事を 引き受けませんでしたか。', null, '["興味がなかったから", "時間がなかったから", "給料が安かったから", "自分より適した人がいたから"]'::jsonb, 3, '["おもしろそうだったと言っている", "何とかなったと言っている", "話に出ていない"]'::jsonb, '{"es": "Aceptar habría sido quitarle la oportunidad a quien encajaba mejor.", "en": "Taking it would have taken the chance from someone better suited."}'::jsonb, '["おもしろそうだった", "時間は何とかなった", "適した人の機会を取ることになる"]'::jsonb, null, '{"intro": "男の人と 女の人が 話して います。男の人は どうして その 仕事を 引き受けませんでしたか。", "turnos": [{"quien": "F", "texto": "あの仕事、断ったんですか。"}, {"quien": "M", "texto": "ええ。おもしろそうだったんですけどね。"}, {"quien": "F", "texto": "時間がなかったとか?"}, {"quien": "M", "texto": "時間は何とかなったと思います。ただ、自分より適した人がいるのに引き受けるのは、その人の機会を取ることになるでしょう。"}], "pregunta": "男の人はどうしてその仕事を引き受けませんでしたか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 6),
  ('n2-point-0005', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 運動を 続けられた 理由は 何だと 言って いますか。', null, '["決める場面をなくしたから", "友だちと一緒にしているから", "記録をつけているから", "意志が強いから"]'::jsonb, 0, '["話に出ていない", "話に出ていない", "意志が強いからではないと言っている"]'::jsonb, '{"es": "Deja la ropa en la entrada: si no hay momento de decidir, no hay momento de dudar.", "en": "She leaves the kit by the door: with no moment of deciding, there''s no moment of hesitating."}'::jsonb, '["意志の強さではない", "着替えを玄関に置く", "決めなくていいことが続く理由"]'::jsonb, null, '{"intro": "女の人が 話して います。女の人は 運動を 続けられた 理由は 何だと 言って いますか。", "turnos": [{"quien": "F", "texto": "三年続いています。意志が強いからではありません。着替えを玄関に置いておくだけです。やろうと決める場面をなくしてしまえば、迷う余地がないんです。決めなくていいことが、いちばん続く理由でした。"}], "pregunta": "女の人は運動を続けられた理由は何だと言っていますか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 6),
  ('n2-point-0006', 'N2', 'point', null, 0, '問題では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人の 意見が 分かれて いるのは どの点ですか。', null, '["商品を知ってもらう必要があるか", "値下げという方法がよいか", "客が離れるかどうか", "値下げすれば売れるかどうか"]'::jsonb, 1, '["女の人も賛成だと言っている", "女の人だけが述べており対立点ではない", "女の人も売れるだろうと認めている"]'::jsonb, '{"es": "Coinciden en el fin y en que bajar el precio vende; discrepan sólo en si ese es el camino.", "en": "They agree on the goal and that cutting prices sells; they differ only on whether that''s the way."}'::jsonb, '["売れることは女の人も認めている", "知ってもらうことにも賛成", "分かれるのは方法の是非"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 話して います。二人の 意見が 分かれて いるのは どの点ですか。", "turnos": [{"quien": "M", "texto": "値下げすれば売れると思うんです。"}, {"quien": "F", "texto": "売れるでしょうね。でも、値段を戻すときに客が離れます。"}, {"quien": "M", "texto": "一時的でも、まず知ってもらわないと。"}, {"quien": "F", "texto": "知ってもらうのは賛成です。その方法が値下げでいいのか、というだけで。"}], "pregunta": "二人の意見が分かれているのはどの点ですか。"}'::jsonb, null, '["ポイント理解"]'::jsonb, 6),
  ('n2-gaiyou-0001', 'N2', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何に ついて 話して いますか。', null, '["覚えることと理解することの違い", "効率のよい暗記の方法", "人前での説明の仕方", "記憶力の鍛え方"]'::jsonb, 0, '["方法の説明はしていない", "話す技術の話ではない", "鍛え方には触れていない"]'::jsonb, '{"es": "Distingue las dos: lo memorizado no se puede explicar; sólo se explica lo que se ha conectado con otra cosa.", "en": "She separates the two: what''s memorised can''t be explained; only what''s connected to something else can."}'::jsonb, '["覚えたものは説明できない", "説明できるのはつなげたもの", "暗記で止まることが問題"]'::jsonb, null, '{"intro": "講演で 女の人が 話して います。", "turnos": [{"quien": "F", "texto": "私たちは、覚えることと理解することを同じものだと思いがちです。しかし、覚えただけのものは説明できません。説明できるのは、ほかの何かとつなげたものだけです。ですから、暗記が悪いのではなく、暗記で止まってしまうことが問題なのです。"}], "pregunta": "女の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 5),
  ('n2-gaiyou-0002', 'N2', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は 何に ついて 話して いますか。', null, '["日曜日の売上の伸ばし方", "休むことの必要性", "料理の味の作り方", "店の場所の選び方"]'::jsonb, 1, '["あえて閉めると述べている", "味は例として出ただけ", "場所の話はしていない"]'::jsonb, '{"es": "Cierra en domingo aun sabiendo que vendería: descansar es lo que le permite seguir el año próximo.", "en": "He closes on Sundays knowing he''d sell: resting is what lets him keep going next year."}'::jsonb, '["開ければ売れる", "休まないと同じ味を出せない", "続けるために稼げる日を閉める"]'::jsonb, null, '{"intro": "ラジオで 店主が 話して います。", "turnos": [{"quien": "M", "texto": "うちの店は、日曜を休みにしています。開ければ売れます。でも、休まないと、来年も同じ味を出せるかどうか分かりません。長く続けることを選ぶなら、稼げる日をあえて閉めることも必要なんです。"}], "pregunta": "男の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 5),
  ('n2-gaiyou-0003', 'N2', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何に ついて 話して いますか。', null, '["会議の進め方", "報告書の内容の質", "様式を決めた理由", "文章を速く書く方法"]'::jsonb, 2, '["会議の話はしていない", "中身の質には触れていない", "速さではなく探す時間の話"]'::jsonb, '{"es": "Explica por qué fijó un formato: escribir cuesta un poco más, leer cuesta mucho menos.", "en": "She explains why she fixed a format: a little more effort writing, far less effort reading."}'::jsonb, '["以前は自由に書いてもらっていた", "読む側が探す時間が長かった", "全体としては早い"]'::jsonb, null, '{"intro": "会議で 女の人が 話して います。", "turnos": [{"quien": "F", "texto": "報告書の様式を変えました。以前は自由に書いてもらっていましたが、読む側が探す時間のほうが長くなっていたんです。書く手間を少し増やして、読む手間を大きく減らす。全体としては、これが早いのです。"}], "pregunta": "女の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 5),
  ('n2-gaiyou-0004', 'N2', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '先生は 何に ついて 話して いますか。', null, '["試験問題の作り方", "授業の時間の配分", "学生の成績の付け方", "質問が出ないときの考え方"]'::jsonb, 3, '["試験の話はしていない", "時間配分の話はしていない", "成績の話はしていない"]'::jsonb, '{"es": "Sostiene que el silencio no prueba comprensión y que mover las manos es lo que produce preguntas.", "en": "He argues silence doesn''t prove understanding, and that doing the work is what produces questions."}'::jsonb, '["質問がないのは分かった証拠ではない", "分からない場所が分からない段階がある", "手を動かすと詰まった所が質問になる"]'::jsonb, null, '{"intro": "大学で 先生が 話して います。", "turnos": [{"quien": "M", "texto": "質問がないのは、分かった証拠ではありません。むしろ、どこが分からないかが分からない段階では、質問は作れないんです。ですから私は、まず手を動かしてもらいます。やってみて詰まったところが、そのまま質問になります。"}], "pregunta": "先生は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 6),
  ('n2-gaiyou-0005', 'N2', 'gaiyou', null, 0, '問題では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の人は 何に ついて 話して いますか。', null, '["図書館の役目の変化", "本の貸し出しの手続き", "利用者を増やす方法", "読む本の選び方"]'::jsonb, 0, '["手続きの説明はしていない", "利用者はすでに増えている", "選び方の話はしていない"]'::jsonb, '{"es": "Los préstamos bajan pero los usuarios suben: la función pasa de prestar libros a prestar un sitio.", "en": "Loans fall while users rise: the role shifts from lending books to lending a place."}'::jsonb, '["利用者は増えている", "減ったのは貸出数", "本を貸すことから場所を貸すことへ"]'::jsonb, null, '{"intro": "図書館で 職員が 話して います。", "turnos": [{"quien": "F", "texto": "本を借りる人が減ったと言われますが、この図書館では利用者は増えています。減ったのは貸出数です。皆さん、館内で調べて、必要なところだけ写して帰られる。図書館の役目は、本を貸すことから、場所を貸すことに移りつつあるのだと思います。"}], "pregunta": "女の人は何について話していますか。"}'::jsonb, null, '["概要理解"]'::jsonb, 6),
  ('n2-tougou_choukai-0001', 'N2', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人は どこへ 行くことに しましたか。', null, '["近くの山の温泉", "海", "まだ決まっていない", "遠くの温泉"]'::jsonb, 0, '["日焼けが心配だと言われた", "見積もりを取ることまで決まった", "遠いと交通費がかかる"]'::jsonb, '{"es": "Playa fuera por el sol, lejos fuera por el coste: el balneario cercano cumple las dos condiciones.", "en": "The beach is out for the sun, far is out for the cost: the nearby hot spring meets both conditions."}'::jsonb, '["海は日焼けが心配", "遠いと交通費がかかる", "近くて温泉なら山のほう"]'::jsonb, null, '{"intro": "会社で 男の人と 女の人が 社員旅行の 行き先に ついて 話して います。", "turnos": [{"quien": "M", "texto": "社員旅行、海がいいと思うんですよ。夏ですし。"}, {"quien": "F", "texto": "私は温泉に一票です。海は日焼けが心配で。"}, {"quien": "M", "texto": "予算を考えると、遠いと交通費がかかりますね。"}, {"quien": "F", "texto": "近くて温泉なら、山のほうにありますよ。日帰りでも行けます。"}, {"quien": "M", "texto": "じゃあ、そこで見積もりを取りましょう。"}], "pregunta": "二人はどこへ行くことにしましたか。"}'::jsonb, null, '["統合理解"]'::jsonb, 6),
  ('n2-tougou_choukai-0002', 'N2', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '男の人は どれを 買うことに しましたか。', null, '["軽くて静かなもの", "吸う力が強いもの", "電池式のもの", "まだ決めていない"]'::jsonb, 1, '["吸う力が普通では困ると言っている", "途中で切れるのは避けたいと言っている", "重くても力があるほうにすると言っている"]'::jsonb, '{"es": "El pelo del perro pesa más que la ligereza, y los veinte minutos le incomodan: se queda con la potente.", "en": "Dog hair outweighs lightness, and the twenty-minute limit bothers him: he takes the powerful one."}'::jsonb, '["階段があるので軽いほうがよかった", "犬の毛が取れないと困る", "途中で切れるのは避けたい"]'::jsonb, null, '{"intro": "店で 店員が 三種類の 掃除機に ついて 説明して います。そのあと 客が 考えて います。", "turnos": [{"quien": "F", "texto": "こちらは軽くて静かですが、吸う力は普通です。こちらは吸う力が強い代わりに、少し重くなります。三つ目は電池式で、コードがいりませんが、使える時間が二十分です。"}, {"quien": "M", "texto": "家に階段があるから、軽いのがいいんですよね。でも、犬の毛が取れないと困るな。電池式は二十分か。うちは狭いから足りるけど、途中で切れるのは避けたい。重くても力があるほうにします。"}], "pregunta": "男の人はどれを買うことにしましたか。"}'::jsonb, null, '["統合理解"]'::jsonb, 6),
  ('n2-tougou_choukai-0003', 'N2', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '二人は どの 案を 選びましたか。', null, '["三つとも行う案", "値段を下げる案", "商品の説明を書き直す案", "広告を増やす案"]'::jsonb, 2, '["三つ行う話は出ていない", "利益が減るのは避けたいと言っている", "予算が厳しいと言っている"]'::jsonb, '{"es": "Sin presupuesto y sin margen para perder beneficio, sólo queda la vía lenta pero gratuita.", "en": "With no budget and no room to lose profit, only the slow but free option is left."}'::jsonb, '["広告は費用が高い", "予算は今期厳しい", "値下げは利益が減る"]'::jsonb, null, '{"intro": "会社で 女の人が 三つの 案を 説明して います。そのあと 男の人と 話して います。", "turnos": [{"quien": "F", "texto": "案は三つです。一つ目は広告を増やす案。費用は高いですが、すぐ効果が出ます。二つ目は商品の説明を書き直す案。費用はほとんどかかりませんが、効果が出るまで時間がかかります。三つ目は値段を下げる案。すぐ売れますが、利益が減ります。"}, {"quien": "M", "texto": "すぐ効果がほしいところですが、予算は今期もう厳しくて。"}, {"quien": "F", "texto": "値下げなら費用はかかりませんよ。"}, {"quien": "M", "texto": "ただ、利益が減るのは避けたい。時間はかかりますが、説明を書き直す案でいきましょう。"}, {"quien": "F", "texto": "分かりました。"}], "pregunta": "二人はどの案を選びましたか。"}'::jsonb, null, '["統合理解"]'::jsonb, 6),
  ('n2-tougou_choukai-0004', 'N2', 'tougou_choukai', null, 0, '問題では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。話を聞いて、1から4の中から、最もよいものを一つ選んでください。', '女の学生は どちらの 授業を 取りますか。', null, '["どちらも取らない", "木曜の授業", "両方とも取る", "月曜の授業"]'::jsonb, 3, '["取らない話は出ていない", "まとめて覚えるのは苦手だと言っている", "両方の話は出ていない"]'::jsonb, '{"es": "Prefiere avanzar poco a poco, y el lunes son tres trabajos sin examen final.", "en": "She prefers steady progress, and Monday means three assignments and no final exam."}'::jsonb, '["月曜はレポート三回、試験なし", "木曜は試験一回だが範囲は全部", "女の学生は毎週少しずつが合っている"]'::jsonb, null, '{"intro": "大学で 男の学生と 女の学生が 授業の 選び方に ついて 話して います。", "turnos": [{"quien": "M", "texto": "月曜の授業、レポートが三回もあるんだって。"}, {"quien": "F", "texto": "きついね。でも、試験がないのはいいな。"}, {"quien": "M", "texto": "木曜のほうは試験一回だけ。ただ、範囲が全部だって。"}, {"quien": "F", "texto": "私は毎週少しずつやるほうが合ってる。まとめて覚えるのは苦手だから。"}, {"quien": "M", "texto": "じゃあ月曜だね。僕は逆で、まとめてやるほうが楽だから木曜にするよ。"}], "pregunta": "女の学生はどちらの授業を取りますか。"}'::jsonb, null, '["統合理解"]'::jsonb, 6),
  ('n2-tanbun-0001', 'N2', 'tanbun', 'n2-tanbun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は、収納を工夫することについてどのように考えているか。', null, '["物を捨てずに済ませてしまうので、片づけとは逆の結果になりうる", "片づけ方を知らない人には向いていない", "収納用品を買えば、半年で部屋がきれいになる", "片づけの第一歩として、まず取り組むべきだ"]'::jsonb, 0, '["本文にない", "調査結果を逆に読んでいる", "本文と逆"]'::jsonb, '{"es": "El texto dice que cuantos más recipientes se compran, peor está el cuarto medio año después, porque uno acaba no tirando nada. La opción 3 lee el estudio al revés.", "en": "The text says the more containers people buy, the worse the room is six months later, because they end up throwing nothing away. Option 3 reads the study backwards."}'::jsonb, '["収納用品を買い足した家庭ほど半年後の状態が悪い → comprar cajas empeora la cosa", "入れ物が増えれば捨てずに済む → esa es la razón", "似ているようで正反対 → la tesis"]'::jsonb, '{"texto": "「片づけが苦手だ」と言う人の多くは、実は片づけ方を知らないのではなく、物を減らす決心がつかないだけらしい。ある調査によると、収納用品を買い足した家庭ほど、半年後の部屋の状態が悪くなっていたという。入れ物が増えれば、捨てずに済んでしまうからだ。つまり、収納を工夫することと片づけることは、似ているようで正反対の行為なのかもしれない。", "notas": [{"termino": "収納用品", "glosa": "物をしまうための箱や棚"}]}'::jsonb, null, null, '["随筆"]'::jsonb, 3),
  ('n2-tanbun-0002', 'N2', 'tanbun', 'n2-tanbun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「勇気の問題に見えて、実は環境の問題なのだ」とあるが、どういうことか。', null, '["間違いを恐れない強い気持ちを持つことが何より大切だということ", "間違えても困らない相手がいるかどうかで、恐れの大きさが変わるということ", "外国語は環境のよい国で学ぶべきだということ", "助言をする人の態度に問題があるということ"]'::jsonb, 1, '["筆者が役に立たないと言っている助言そのもの", "「環境」を国のことだと文字通りに取った", "本文にない"]'::jsonb, '{"es": "Para el autor el miedo no se quita por voluntad, sino que se encoge solo cuando hay alguien que te repregunta y te corrige sin dramas. La 3 toma «entorno» como país, que no es lo que dice.", "en": "For the author fear doesn''t go away by willpower; it shrinks on its own when someone asks again and corrects you without fuss. Option 3 takes ''environment'' to mean country, which isn''t what''s said."}'::jsonb, '["恐れは意志で消せない → el consejo habitual no sirve", "間違えても困らない場所を用意する → la propuesta", "聞き返してくれる相手がいれば恐れは小さくなる → el porqué"]'::jsonb, '{"texto": "外国語を学ぶとき、間違いを恐れるなとよく言われる。しかし私は、恐れるなという助言はあまり役に立たないと思っている。恐れは意志で消せるものではないからだ。それよりも、間違えても困らない場所を先に用意するほうがいい。聞き返してくれる相手、笑って直してくれる相手がいれば、恐れは自然に小さくなる。勇気の問題に見えて、実は環境の問題なのだ。", "notas": []}'::jsonb, null, null, '["随筆", "比喩"]'::jsonb, 4),
  ('n2-chuubun-0001', 'N2', 'chuubun', 'n2-chuubun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '先輩に叱られたのは、どんなことに対してか。', null, '["困った時点で報告しなかったこと", "仕事が終わるのが遅かったこと", "大きな失敗をしたこと", "報告の仕方が丁寧でなかったこと"]'::jsonb, 0, '["本文にない", "本文が「失敗そのものではなかった」と否定している", "本文にない"]'::jsonb, '{"es": "El texto dice expresamente que no le riñeron por el error, sino por avisar cuando ya había terminado en vez de cuando surgió el problema.", "en": "The text says outright that he wasn''t told off for the mistake, but for reporting once it was over instead of when the trouble started."}'::jsonb, '["叱られたのは失敗そのものではなかった → no fue por el error", "困った時点で言え → fue por el momento del aviso"]'::jsonb, '{"texto": "会社に入ったばかりのころ、先輩に「報告は早いほどいい」と言われた。私はそれを、仕事が終わったらすぐ知らせろという意味だと受け取っていた。実際、しばらくはそのつもりで働いていたし、それで困ったこともなかった。\nところがある日、大きな失敗をして報告が遅れたとき、先輩に叱られたのは失敗そのものではなかった。「終わってから言うな、困った時点で言え」と言われたのだ。自分では、きちんと片をつけてから伝えるほうが迷惑をかけないと思っていたのだが、先輩の顔を見て、その考えが逆であることに気づいた。\n考えてみれば当然である。終わった仕事の報告は、聞く側にとってはただの記録にすぎない。しかし途中の報告は、まだ手の打ちようがある情報だ。前者は過去の話で、後者は未来の話なのだ。記録は後からでも読めるが、未来の話は、その時に聞かなければ意味を失う。\nそれ以来、私は「順調です」という報告をしないことにしている。順調なら黙っていても誰も困らない。報告が必要なのは、いつも順調でないときのほうなのだから。", "notas": [{"termino": "手の打ちよう", "glosa": "対処する方法"}]}'::jsonb, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-chuubun-0002', 'N2', 'chuubun', 'n2-chuubun-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「前者は過去の話で、後者は未来の話なのだ」とあるが、「後者」とは何か。', null, '["終わった仕事の報告", "途中の報告", "先輩の助言", "失敗の記録"]'::jsonb, 1, '["前者のほう", "本文の別の要素", "本文の別の要素"]'::jsonb, '{"es": "前者 es el informe de un trabajo ya terminado y 後者 el informe a medio camino, que todavía permite reaccionar.", "en": "前者 is the report on finished work and 後者 the mid-way report, which still allows you to act."}'::jsonb, '["終わった仕事の報告＝前者", "途中の報告＝後者、まだ手の打ちようがある"]'::jsonb, null, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-chuubun-0003', 'N2', 'chuubun', 'n2-chuubun-g001', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が「順調です」という報告をしないのはなぜか。', null, '["報告が多いと迷惑をかけるから", "先輩にそう命じられたから", "順調でないときこそ報告が必要だと考えているから", "順調なときは報告する時間がないから"]'::jsonb, 2, '["本文にない", "先輩の言葉は別の内容", "本文にない"]'::jsonb, '{"es": "Su conclusión es que si todo va bien no pasa nada por callar; el informe hace falta justo cuando las cosas no van bien.", "en": "His conclusion is that when things go well silence costs nothing; the report is needed precisely when they don''t."}'::jsonb, '["順調なら黙っていても困らない", "報告が必要なのは順調でないときのほう"]'::jsonb, null, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-tanbun-0003', 'N2', 'tanbun', 'n2-tanbun-g003', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は、専門家の説明が分かりにくい理由を どう 考えて いるか。', null, '["専門用語が多いから", "知識が足りないから", "聞き手のつまずきを思い出せないから", "説明の練習をしていないから"]'::jsonb, 2, '["本文にない", "知識が多すぎるからではないと述べている", "本文にない"]'::jsonb, '{"es": "El que ya entendió pierde el recuerdo de no entender, y con él la brújula del oyente.", "en": "Once you understand, you lose the memory of not understanding — and with it the listener''s compass."}'::jsonb, null, '{"texto": "専門家の説明が分かりにくいのは、知識が多すぎるからではない。聞き手がどこでつまずくかを、もう思い出せなくなっているからだ。一度分かってしまったことは、分からなかったころの感覚ごと消えてしまう。だから、教えるのがうまい人は、たいてい自分も最近つまずいた人である。知識の量ではなく、記憶の新しさが、説明の質を決めている。", "notas": []}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n2-tanbun-0004', 'N2', 'tanbun', 'n2-tanbun-g004', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考えに 合う ものは どれか。', null, '["選択肢は多いほうがよい", "朝は早く起きるべきだ", "服に関心を持つべきだ", "選ばずに済むことが便利さにつながる"]'::jsonb, 3, '["多さと便利さは同じではないと述べている", "本文にない", "関心の有無は問題にしていない"]'::jsonb, '{"es": "Decidir de antemano qué se descarta convierte el tiempo de duda en tiempo libre.", "en": "Deciding in advance what to drop turns hesitation time into free time."}'::jsonb, null, '{"texto": "便利さは、選択肢の多さと同じではない。むしろ、選ばなくてよくなることのほうが多い。毎朝同じ服を着る人がいるのは、服に関心がないからではなく、朝の判断を一つ減らすためだ。何を捨てるかを先に決めておけば、迷っていた時間はそのまま自由な時間になる。増やすことばかりが豊かさだと考えると、この単純な計算を見落とす。", "notas": []}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n2-tanbun-0005', 'N2', 'tanbun', 'n2-tanbun-g005', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は 何が 問題だと 言って いるか。', null, '["結びつける手順を教わっていないこと", "地図を読む才能がないこと", "景色が変わりやすいこと", "地図の記号が多すぎること"]'::jsonb, 0, '["才能の問題ではないと述べている", "本文にない", "記号の数は問題にしていない"]'::jsonb, '{"es": "Cierra diciéndolo: lo que se atribuye al talento suele ser cuestión de procedimiento.", "en": "He closes by saying it: what gets blamed on talent is usually a matter of procedure."}'::jsonb, null, '{"texto": "地図が読めない人がいるのではない。地図と目の前の景色を結びつける手順を、教わっていない人がいるだけだ。まず自分がどちらを向いているかを決める。次に、動かないものを一つ探す。この二つを飛ばして地図だけを見ても、線と記号の集まりにしか見えない。才能の問題にされてきたことの多くは、実は手順の問題である。順序を言葉にできる人が、教えられる人だ。", "notas": []}'::jsonb, null, null, '["短文"]'::jsonb, 5),
  ('n2-chuubun-0004', 'N2', 'chuubun', 'n2-chuubun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は 写真を 撮ることに ついて、どう 考えて いるか。', null, '["記録より記憶のほうが価値がある", "観光地では禁止すべきだ", "調査の結果は信用できない", "撮ること自体は悪くない"]'::jsonb, 3, '["両方手に入ると述べている", "禁止すればよい話ではないと述べている", "調査を根拠として使っている"]'::jsonb, '{"es": "Lo dice explícitamente y hasta le encuentra ventajas: fotografiar afina la atención.", "en": "He says so outright and even finds a benefit: photographing sharpens attention."}'::jsonb, null, '{"texto": "観光地に行くと、まず写真を撮る人が増えた。景色を見る前に、画面ごしに景色を見ている。構図を整えているあいだにも、目の前の光は少しずつ変わっていく。\n写真を撮ること自体を悪いとは思わない。撮ることで注意が細かくなり、そこにある形や色に気づくこともある。問題は、撮った後に何も見ていない場合だ。撮影が「見た」ことの代わりになってしまうと、記録は残っても記憶は残らない。\nある調査では、展示物を撮影した人のほうが、撮らなかった人より内容を覚えていなかったという。機械に預けた記憶は、自分の中には残らないらしい。覚える必要がないと判断した瞬間に、頭は手を抜くのだろう。撮る前に一度、何を残したいのかを言葉にしてみるといい。目的のない一枚は、あとで見返しても何も語らない。\nとはいえ、写真を禁止すればよいという話でもない。撮ったあとに一度、機械を下ろして自分の目で見る。それだけで、記録と記憶の両方が手に入る。順番の問題にすぎないのだ。", "notas": []}'::jsonb, null, null, '["中文"]'::jsonb, 5),
  ('n2-chuubun-0005', 'N2', 'chuubun', 'n2-chuubun-g002', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 勧めて いるのは どういう ことか。', null, '["撮った後に自分の目で見ること", "写真を撮らずに景色を見ること", "撮影の枚数を減らすこと", "記録を残さないこと"]'::jsonb, 0, '["撮ること自体は否定していない", "枚数の話は出ていない", "記録も手に入れたいと述べている"]'::jsonb, '{"es": "Su propuesta es de orden: dispara, baja la cámara y mira.", "en": "His proposal is about order: shoot, lower the camera, and look."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 5),
  ('n2-chuubun-0006', 'N2', 'chuubun', 'n2-chuubun-g003', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '直せない ものが 増えて いるのは、なぜだと 言って いるか。', null, '["修理する人が減ったから", "作る側が修理を想定していないから", "部品の値段が上がったから", "客が買い替えを望むから"]'::jsonb, 1, '["直したい人は減っていないと述べている", "手に入らないとは書いてあるが値段の話ではない", "安いと分かっていても持ち込む客がいる"]'::jsonb, '{"es": "Piezas inhallables, garantía que se pierde, tornillos ocultos: el diseño no cuenta con la reparación.", "en": "Unobtainable parts, voided warranties, hidden screws: the design doesn''t allow for repair."}'::jsonb, null, '{"texto": "壊れたら直して使う、という言い方は美しいが、現実には直せないものが増えている。部品が手に入らない、開けると保証が切れる、そもそもねじが見えない。作る側が、直されることを想定していないのだ。\n一方で、直したい人は減っていない。町の修理店には、買い替えたほうが安いと分かっていても持ち込む客が来る。彼らが払っているのは修理代ではなく、その物と過ごした時間に対する代金だろう。ある店主は「直せるかどうかより、直したいかどうかで決めている」と言っていた。\n経済的に見れば不合理である。しかし、すべてを金額で比べる習慣は、案外新しいものだ。値段で測れないものまで値段で測ろうとすれば、答えはいつも「捨てろ」になる。祖母は割れた茶碗を継いで使っていたが、あれが安上がりだったとは思えない。継いだ跡のある茶碗は、割れる前とは別の物になっていた。\n物を大事にするとは、長く使うことではなく、手をかける相手を選ぶことなのかもしれない。", "notas": [{"termino": "継ぐ", "glosa": "割れたものをつなぎ合わせて直す"}]}'::jsonb, null, null, '["中文"]'::jsonb, 5),
  ('n2-chuubun-0007', 'N2', 'chuubun', 'n2-chuubun-g003', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考えに 最も 近い ものは どれか。', null, '["何でも長く使うべきだ", "修理は経済的に得である", "手をかける相手を選ぶことが大切だ", "昔の習慣に戻るべきだ"]'::jsonb, 2, '["長く使うことではないと述べている", "不合理だと認めている", "習慣の新しさを指摘しただけ"]'::jsonb, '{"es": "La última frase: cuidar no es alargar, sino elegir a qué le dedicas trabajo.", "en": "The last line: caring isn''t making things last, it''s choosing what you put work into."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 6),
  ('n2-chuubun-0008', 'N2', 'chuubun', 'n2-chuubun-g004', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「二種類の 静けさ」とは、どういう ものか。', null, '["よい職場と悪い職場", "朝の静けさと夜の静けさ", "大きい音と小さい音", "集中している静けさと、話しかけられない静けさ"]'::jsonb, 3, '["静けさの分類であって職場の分類ではない", "時間による分類ではない", "音の大きさの分類ではない"]'::jsonb, '{"es": "El texto las nombra: la del que se concentra y la del que no se atreve a hablar.", "en": "The text names them: the quiet of concentration and the quiet of not daring to speak."}'::jsonb, null, '{"texto": "静かな職場がよい職場だと、長いあいだ信じられてきた。私語がない、電話の声が小さい、誰も立ち歩かない。管理する側から見れば、たしかに整って見える。\nしかし、静けさには二種類ある。集中している静けさと、話しかけられない静けさだ。外から見ただけでは区別がつかない。後者の職場では、質問が生まれない。声を出さないことが評価される場所では、黙っているほうが安全になるからだ。分からないまま作業が進み、最後にまとめて事故になる。\n私が以前いた職場は、正直うるさかった。誰かが独り言のように「これ、変じゃない?」とつぶやくと、近くの人が顔を上げる。そこで止まった問題がいくつもあった。あの音は無駄ではなかったのだ。あとから大きな問題が出てきたのは、いつも静かにしろと言われた職場のほうだった。\n静けさを目標にするのはやめたほうがいい。目標は、必要なときに声が出ることである。結果として静かなら、それはよい静けさだ。", "notas": []}'::jsonb, null, null, '["中文"]'::jsonb, 5),
  ('n2-chuubun-0009', 'N2', 'chuubun', 'n2-chuubun-g004', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 目標に すべきだと 言って いるのは 何か。', null, '["必要なときに声が出ること", "事故を完全になくすこと", "私語をなくすこと", "職場を静かにすること"]'::jsonb, 0, '["事故は結果として挙げた例", "つぶやきが問題を止めたと述べている", "静けさを目標にするなと述べている"]'::jsonb, '{"es": "Lo dice al final: el objetivo es que salga la voz cuando hace falta; el silencio, si llega, es consecuencia.", "en": "He says it at the end: the goal is that a voice comes out when needed; quiet, if it comes, is a by-product."}'::jsonb, null, null, null, null, '["中文"]'::jsonb, 6),
  ('n2-tougou-0001', 'N2', 'tougou', 'n2-tougou-g001', 0, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '授業の 録画に ついて、AとBが 共通して 認めて いることは 何か。', null, '["録画には学習上の利点があること", "録画は授業の代わりになること", "通学の時間はすべて無駄であること", "教室に集まる必要はないこと"]'::jsonb, 0, '["Bは代わりにはならないと述べている", "Bは通学時間について述べていない", "Bは同じ部屋にいる価値を認めている"]'::jsonb, '{"es": "B empieza con «no lo niego»: los dos aceptan que grabar aporta algo; discrepan en si sustituye a la clase.", "en": "B opens with ''I don''t deny it'': both accept recording has value; they differ on whether it replaces the class."}'::jsonb, null, '{"texto": "A\n大学の授業は録画して、いつでも見られるようにすべきだ。通学に往復二時間かけている学生にとって、その二時間はそのまま学習時間になりうる。理解の速さは人によって違うのだから、止めたり戻したりできることの価値は大きい。教室に集めることを当然としてきた制度のほうが、そろそろ説明を求められている。\n\nB\n録画を否定はしない。ただ、それを授業の代わりと呼ぶのは無理がある。授業の価値の一部は、分からない顔をした人が同じ部屋にいることにある。自分だけがつまずいているのではないと分かるから、手が挙がるのだ。一人で画面を見ていると、つまずきは個人の失敗として処理されてしまう。録画は補助であって、置き換えではない。", "notas": []}'::jsonb, null, null, '["統合理解"]'::jsonb, 6),
  ('n2-tougou-0002', 'N2', 'tougou', 'n2-tougou-g001', 1, '次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '教室に 集まることに ついて、AとBの 立場は どう ちがうか。', null, '["どちらも不要だとしている", "Aは説明が必要だとし、Bはつまずきを共有する場として価値を認めている", "Aは必要だとし、Bは不要だとしている", "どちらも録画そのものに反対している"]'::jsonb, 1, '["Bは価値を認めている", "AとBの立場が逆", "どちらも録画を否定していない"]'::jsonb, '{"es": "A pide justificar la asistencia presencial; B la defiende porque ver a otros atascados es lo que hace levantar la mano.", "en": "A asks the in-person model to justify itself; B defends it because seeing others stuck is what makes hands go up."}'::jsonb, null, null, null, null, '["統合理解"]'::jsonb, 6),
  ('n2-shuchou-0001', 'N2', 'shuchou', 'n2-shuchou-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が 答えを 言わないように しているのは、なぜか。', null, '["判断に必要な材料が足りないから", "相手に嫌われたくないから", "責任を取りたくないから", "助言する時間がないから"]'::jsonb, 0, '["冷たいと思われることもあると認めている", "責任逃れではないと述べている", "本文にない"]'::jsonb, '{"es": "Sólo recibe una parte de la situación, y encima seleccionada por el otro.", "en": "He only gets part of the situation, and a part the other person selected at that."}'::jsonb, null, '{"texto": "助言を求められたとき、私はできるだけ答えを言わないようにしている。冷たいと思われることもあるが、理由がある。\n助言というのは、こちらの経験を相手の状況に当てはめる作業である。ところが、当てはめる先の状況を、こちらは十分に知らない。相手が話してくれるのは、判断に必要な情報のうちのごく一部にすぎない。しかも、その一部を選んだのは相手自身である。つまり、こちらが受け取る材料は、すでに相手の見方で切り取られた後のものだ。何を話さないかという選択にこそ、その人の思い込みが表れる。\nそれでも助言はできてしまう。切り取られた材料でも、それらしい結論は組み立てられるからだ。そのうえ、助言する側には気持ちのよさがある。役に立った気になれるし、頼られたという感覚も残る。危ういのは、この気持ちのよさが、判断の質とはまったく無関係に発生することである。よく効いた助言と、ただ言い切っただけの助言とは、言った側からは区別がつかない。区別がつくのは、たいてい何年もあとになってからだ。\nでは何をするか。私は質問をすることにしている。「その選択をしなかったら、何が起きると思う?」「いちばん避けたいのはどれ?」。答えるのは相手だから、材料の不足はそのまま相手の側で補われる。うまくいけば、話しているうちに相手の中で順番が決まっていく。急がずに黙って待っていると、相手のほうから条件を並べ始めることも多い。\nこれは責任を逃れるための方法ではない。むしろ逆で、答えを渡してしまうほうが楽なのだ。渡された答えは、うまくいかなかったときに渡した人のせいにできる。自分で決めた答えは、そうはいかない。決めるまでの過程を覚えているから、次に似た場面が来たときにそれが使える。長い目で見れば、決める練習を重ねた人のほうが強い。\nもちろん、急いでいるときや、明らかに危険な選択をしようとしているときは別である。そういうときは、はっきり言う。原則は原則であって、規則ではない。", "notas": [{"termino": "助言", "glosa": "アドバイス、考えを言って助けること"}]}'::jsonb, null, null, '["主張理解"]'::jsonb, 6),
  ('n2-shuchou-0002', 'N2', 'shuchou', 'n2-shuchou-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「この 気持ちの よさ」が 危ういのは、なぜか。', null, '["経験が足りないと感じるから", "助言の質と関係なく生まれるから", "相手を怒らせることがあるから", "考える時間がかかるから"]'::jsonb, 1, '["経験の不足ではなく情報の不足が問題", "怒りの話は出ていない", "時間の話は出ていない"]'::jsonb, '{"es": "La satisfacción aparece igual si el consejo era bueno o si sólo sonaba rotundo.", "en": "The good feeling arrives whether the advice was sound or merely delivered with conviction."}'::jsonb, null, null, null, null, '["主張理解"]'::jsonb, 6),
  ('n2-shuchou-0003', 'N2', 'shuchou', 'n2-shuchou-g001', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者の 考えに 合う ものは どれか。', null, '["助言は絶対にすべきではない", "質問は責任を逃れるための方法である", "決める練習を重ねた人のほうが強い", "危険なときでも黙っているべきだ"]'::jsonb, 2, '["急ぐときや危険なときははっきり言うと述べている", "むしろ逆だと述べている", "そういうときは別だと述べている"]'::jsonb, '{"es": "Es su conclusión: dar la respuesta es lo cómodo; decidir uno mismo es lo que entrena.", "en": "That''s his conclusion: handing over the answer is the easy path; deciding for yourself is what trains you."}'::jsonb, null, null, null, null, '["主張理解"]'::jsonb, 6),
  ('n2-jouhou-0001', 'N2', 'jouhou', 'n2-jouhou-g001', 0, '右のページは、会社の健康診断の案内である。これを読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '5月に 入社した 山田さんは、どう すれば よいか。', null, '["今回は受けなくてよい", "社外の医療機関で受ける", "6月の健康診断を必ず受ける", "総務部の承認を得てから受ける"]'::jsonb, 0, '["受けられなかった場合の手続き", "4月以降の入社は対象外", "社外で受ける場合の手続き"]'::jsonb, '{"es": "Quien entró en abril o después ya pasó el reconocimiento de ingreso y queda fuera de esta ronda.", "en": "Anyone who joined in April or later already had the entry check-up and is out of this round."}'::jsonb, null, '{"texto": "【社員健康診断のお知らせ】\n\n■ 日程と会場\n　6月10日（火）〜6月13日（金）　本社3階　会議室\n　6月17日（火）　　　　　　　　　工場棟　医務室\n　いずれも 9:00〜16:00（12:00〜13:00は受付を行いません）\n\n■ 対象\n　全社員（契約社員・パート社員を含む）\n　※ 4月以降に入社した方は、入社時健診を受けているため今回は対象外です。\n\n■ 検査の内容\n　身長・体重・血圧・視力・聴力・血液検査・胸部レントゲン\n　※ 35歳以上の方は、胃の検査も含まれます。\n　※ 妊娠中の方はレントゲン検査を受けられません。事前にお申し出ください。\n\n■ 申し込み\n　5月25日までに、社内システムから希望の日時を登録してください。\n　登録がない場合は、こちらで日時を割り当てます。\n\n■ 当日の注意\n　・検査の10時間前から、水以外は口にしないでください。\n　・薬を飲んでいる方は、事前に医務室へご連絡ください。\n　・眼鏡やコンタクトレンズを使っている方は、当日お持ちください。\n\n■ 受けられなかった場合\n　社外の医療機関で受診し、9月末までに結果を提出してください。\n　費用は会社が負担しますが、事前に総務部の承認が必要です。\n\n※ 工場勤務の方は、6月17日の会場をご利用ください。本社の会場も利用できますが、その場合は上長の許可を得てください。", "notas": [{"termino": "上長", "glosa": "職場で自分より上の立場の人"}]}'::jsonb, null, null, '["情報検索"]'::jsonb, 5),
  ('n2-jouhou-0002', 'N2', 'jouhou', 'n2-jouhou-g001', 1, '右のページは、会社の健康診断の案内である。これを読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', 'この 案内から 分かることは どれか。', null, '["昼休みにも受付をしている", "申し込みをしなくても日時は決まる", "工場勤務の人は本社では受けられない", "受けられなかった場合の費用は自分で払う"]'::jsonb, 1, '["12時から13時は受付を行わない", "上長の許可があれば本社でも受けられる", "費用は会社が負担する"]'::jsonb, '{"es": "«登録がない場合は、こちらで日時を割り当てます»: si no te apuntas, te asignan hora igualmente.", "en": "«If you don''t register, we will assign you a slot» — no sign-up still gets you a time."}'::jsonb, null, null, null, null, '["情報検索"]'::jsonb, 5),
  ('n2-kanji_yomi-0001', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼の提案は会議で<u>採用</u>された。', '採用', '["さいよう", "さいよ", "ざいよう", "さいゆう"]'::jsonb, 0, '["長音を落とした", "濁音にした", "母音を変えた"]'::jsonb, '{"es": "採用（さいよう）. 採 se lee さい y 用 よう. El error más común es comerse el alargamiento: さいよ.", "en": "採用 (saiyō). 採 is さい and 用 よう. The usual slip is dropping the long vowel: さいよ."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0002', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'この道は工事のため<u>通行</u>止めになっている。', '通行', '["つうごう", "つうこう", "とうこう", "つこう"]'::jsonb, 1, '["行を濁音にした", "通をとうと読んだ", "長音なし"]'::jsonb, '{"es": "通行（つうこう）. 通 en compuestos es つう, no とう; y lleva vocal larga.", "en": "通行 (tsūkō). In compounds 通 is つう, never とう, and the vowel is long."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0003', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼女は毎日<u>欠かさず</u>日記をつけている。', '欠かさず', '["きらさず", "なくさず", "かかさず", "たやさず"]'::jsonb, 2, '["同じ活用の別動詞", "同じ活用の別動詞", "同じ活用の別動詞"]'::jsonb, '{"es": "欠かす→欠かさず（かかさず）, «sin faltar un solo día». Los otros tres son verbos distintos con la misma terminación.", "en": "欠かす → 欠かさず (kakasazu), ''without missing a day''. The other three are different verbs with the same ending."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0004', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '<u>険しい</u>山道を三時間かけて登った。', '険しい', '["きびしい", "はげしい", "くやしい", "けわしい"]'::jsonb, 3, '["厳しいと混同", "激しいと混同", "悔しいと混同"]'::jsonb, '{"es": "険しい（けわしい）= escarpado. きびしい es 厳しい, はげしい es 激しい: adjetivos de la misma forma pero otro kanji.", "en": "険しい (kewashii) = steep. きびしい is 厳しい and はげしい is 激しい — same shape, different kanji."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0005', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '新しい制度の<u>導入</u>が検討されている。', '導入', '["どうにゅう", "とうにゅう", "どうにゅ", "どうじゅう"]'::jsonb, 0, '["清音にした", "長音を落とした", "入をじゅうと読んだ"]'::jsonb, '{"es": "導入（どうにゅう）. 導 es どう (sonoro) y 入 にゅう con vocal larga.", "en": "導入 (dōnyū). 導 is どう (voiced) and 入 is にゅう with a long vowel."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0006', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '駅前の<u>商店街</u>は夕方になると賑わう。', '商店街', '["しょうてんかい", "しょうてんがい", "しょてんかい", "しょてんがい"]'::jsonb, 1, '["連濁なし", "両方", "長音なし"]'::jsonb, '{"es": "商店街（しょうてんがい）. 商 lleva vocal larga y 街 se sonoriza a がい tras 店.", "en": "商店街 (shōtengai). 商 has a long vowel and 街 voices to がい after 店."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0001', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '毎朝走るのは<u>けんこう</u>のためだ。', 'けんこう', '["健康", "建康", "健庫", "建庫"]'::jsonb, 0, '["建と健の混同", "康と庫の混同", "両方"]'::jsonb, '{"es": "健康. 健 (persona sana) no 建 (construir); 康 no 庫 (almacén). Se parecen mucho de forma.", "en": "健康. 健 (healthy) not 建 (build); 康 not 庫 (warehouse). They look very similar."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0002', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '先生の<u>こうぎ</u>はとても分かりやすい。', 'こうぎ', '["購義", "講義", "講議", "構義"]'::jsonb, 1, '["同じ部首の購", "義と議の混同", "同じ部首の講/構"]'::jsonb, '{"es": "講義 = clase magistral. 講/構/購 comparten forma; 義 (sentido) no 議 (deliberar).", "en": "講義 = a lecture. 講/構/購 look alike; 義 (meaning) not 議 (to deliberate)."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0003', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '書類の最後に<u>しょめい</u>をしてください。', 'しょめい', '["暑名", "署明", "署名", "諸名"]'::jsonb, 2, '["暑と署の混同", "名と明の混同", "諸と署の混同"]'::jsonb, '{"es": "署名 = firma. 署 (oficina, firmar) no 暑 (calor) ni 諸 (varios).", "en": "署名 = signature. 署 (office, to sign) not 暑 (hot) or 諸 (various)."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0004', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '彼が<u>いがい</u>にも早く着いたので驚いた。', 'いがい', '["以外", "異外", "意害", "意外"]'::jsonb, 3, '["以外との混同", "異と意の混同", "害と外の混同"]'::jsonb, '{"es": "意外 = inesperado. 以外 (いがい) existe pero significa «excepto»: es el fallo clásico del N2.", "en": "意外 = unexpected. 以外 (igai) also exists but means ''except'' — the classic N2 trap."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0005', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'この機械は<u>そうさ</u>が簡単だ。', 'そうさ', '["操作", "捜査", "創作", "装作"]'::jsonb, 0, '["同音の捜査", "そうさくとの混同", "存在しない語"]'::jsonb, '{"es": "操作 = manejo de una máquina. 捜査 (そうさ) es «investigación policial»; 創作 se lee そうさく.", "en": "操作 = operating a machine. 捜査 (sōsa) is a police investigation; 創作 reads sōsaku."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0001', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'その情報はまだ（　）公式のもので、発表はされていない。', '（　）公式', '["非", "未", "無", "不"]'::jsonb, 0, '["未は「まだ〜していない」", "無は「〜がない」", "不は否定一般"]'::jsonb, '{"es": "非公式 = extraoficial. 非〜 niega la naturaleza de algo; 未〜 es «todavía no» y 無〜 es «sin».", "en": "非公式 = unofficial. 非〜 negates what something is; 未〜 means ''not yet'' and 無〜 means ''without''."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0002', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'アンケートの結果、利用者の満足（　）は九割を超えた。', '満足（　）', '["率", "度", "性", "化"]'::jsonb, 1, '["率は割合", "性は性質", "化は変化"]'::jsonb, '{"es": "満足度 = grado de satisfacción. 〜度 mide intensidad; 〜率 mide proporción.", "en": "満足度 = level of satisfaction. 〜度 measures degree; 〜率 measures a ratio."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0003', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '工事は（　）完成のまま中断されている。', '（　）完成', '["非", "反", "未", "無"]'::jsonb, 2, '["非は性質の否定", "反は反対", "無は不在"]'::jsonb, '{"es": "未完成 = sin terminar. 未〜 dice que algo aún no ha llegado a ese estado.", "en": "未完成 = unfinished. 未〜 says something has not yet reached that state."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0004', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '先月より電気（　）が高くなった。', '電気（　）', '["料", "賃", "費", "代"]'::jsonb, 3, '["料は料金の語基", "賃は労働や運送", "費は支出全般"]'::jsonb, '{"es": "電気代 = la factura de la luz. 〜代 es lo que se paga por algo consumido; 〜賃 es por transporte o trabajo.", "en": "電気代 = the electricity bill. 〜代 is what you pay for something consumed; 〜賃 is for transport or labour."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0005', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は責任（　）が強く、仕事を最後までやり遂げる。', '責任（　）', '["感", "性", "心", "力"]'::jsonb, 0, '["性は性質", "心は気持ち一般", "力は能力"]'::jsonb, '{"es": "責任感 = sentido de la responsabilidad. 〜感 es la sensación interna; 〜性 sería una propiedad objetiva.", "en": "責任感 = a sense of responsibility. 〜感 is the inner feeling; 〜性 would be an objective property."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0001', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この計画は（　）に検討したうえで決定したい。', '（　）', '["慎重", "貴重", "尊重", "重大"]'::jsonb, 0, '["「重」を共有", "「重」を共有", "「重」を共有"]'::jsonb, '{"es": "慎重に検討する = estudiarlo con cuidado. Las cuatro comparten el kanji 重, pero sólo 慎重 combina con 検討する.", "en": "慎重に検討する = to look into it carefully. All four share 重, but only 慎重 collocates with 検討する."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0002', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は約束の時間に（　）現れる。', '（　）', '["しっかり", "きっちり", "がっかり", "うっかり"]'::jsonb, 1, '["同じ形の副詞", "同じ形の副詞", "同じ形の副詞"]'::jsonb, '{"es": "きっちり = clavado, exacto. うっかり es «por descuido» y がっかり «decepcionado»: misma forma, sentido incompatible.", "en": "きっちり = exactly, on the dot. うっかり is ''carelessly'' and がっかり ''disappointed'' — same shape, incompatible sense."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0003', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '大雨のため、試合は（　）された。', '（　）', '["廃止", "停止", "中止", "禁止"]'::jsonb, 2, '["「止」を共有", "「止」を共有", "「止」を共有"]'::jsonb, '{"es": "中止 = cancelado por una circunstancia. 禁止 es prohibir, 停止 detener algo en marcha, 廃止 abolir para siempre.", "en": "中止 = called off because of circumstances. 禁止 is to forbid, 停止 to halt something running, 廃止 to abolish for good."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0004', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の話は（　）がなくて、何が言いたいのか分からない。', '（　）', '["へだたり", "かかわり", "つながり", "まとまり"]'::jsonb, 3, '["同じ〜り名詞", "同じ〜り名詞", "同じ〜り名詞"]'::jsonb, '{"es": "まとまりがない = deslavazado, sin hilo. つながり sería «conexión» entre cosas concretas.", "en": "まとまりがない = rambling, with no thread. つながり would be a ''connection'' between specific things."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0005', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼はまだ経験が（　）ので、一人で任せるのは不安だ。', '（　）', '["乏しい", "貧しい", "惜しい", "険しい"]'::jsonb, 0, '["同じ〜しい形容詞", "同じ〜しい形容詞", "同じ〜しい形容詞"]'::jsonb, '{"es": "経験が乏しい = tiene poca experiencia. 貧しい se dice del dinero, no de la experiencia.", "en": "経験が乏しい = short on experience. 貧しい is about money, not experience."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0006', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '新入社員は（　）した態度で質問に答えていた。', '（　）', '["どきどき", "はきはき", "ばらばら", "いきいき"]'::jsonb, 1, '["同じ畳語の副詞", "同じ畳語の副詞", "同じ畳語の副詞"]'::jsonb, '{"es": "はきはきした態度 = con desparpajo, respondiendo claro. いきいき es «lleno de vida» y no describe la manera de contestar.", "en": "はきはきした態度 = crisp and clear in answering. いきいき is ''lively'' and doesn''t describe how one answers."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunmyaku-0007', 'N2', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '先生に注意されて、彼は（　）していた。', '（　）', '["ゆっくり", "はっきり", "しょんぼり", "ぴったり"]'::jsonb, 2, '["同じ〜り副詞", "同じ〜り副詞", "同じ〜り副詞"]'::jsonb, '{"es": "しょんぼり = cabizbajo. Los otros tres son también 〜り pero ninguno describe un estado de ánimo.", "en": "しょんぼり = downcast. The other three are also 〜り adverbs but none describes a mood."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-iikae-0001', 'N2', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'その件については、<u>おって</u>連絡します。', 'おって', '["あとで", "すぐに", "直接", "必ず"]'::jsonb, 0, '["時間の逆", "手段であって時期でない", "確実さであって時期でない"]'::jsonb, '{"es": "おって = más adelante, en su momento. Es la versión formal de あとで.", "en": "おって = later on, in due course. It''s the formal version of あとで."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-iikae-0002', 'N2', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼の説明は<u>くどくて</u>、聞いていて疲れる。', 'くどくて', '["あっさりしていて", "しつこくて", "短くて", "難しくて"]'::jsonb, 1, '["反対の意味", "長さだけの問題ではない", "難易度は別の話"]'::jsonb, '{"es": "くどい = pesado de tanto insistir. あっさりしている es justo lo contrario.", "en": "くどい = tediously insistent. あっさりしている is the exact opposite."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-iikae-0003', 'N2', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '今年は予算が<u>とぼしい</u>。', 'とぼしい', '["ちょうどいい", "増えている", "少ない", "多い"]'::jsonb, 2, '["程度の尺度: 中間", "方向が違う", "程度の尺度: 反対"]'::jsonb, '{"es": "とぼしい = escaso. Los distractores forman una escala de cantidad y sólo «少ない» coincide.", "en": "とぼしい = scarce. The distractors form a scale of quantity and only 少ない matches."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-iikae-0004', 'N2', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', '彼女は<u>たちまち</u>有名になった。', 'たちまち', '["ようやく", "なかなか", "だんだん", "あっという間に"]'::jsonb, 3, '["時間がかかる含み", "時間がかかる含み", "速度が逆"]'::jsonb, '{"es": "たちまち = en un abrir y cerrar de ojos. だんだん sería poco a poco, lo contrario.", "en": "たちまち = in no time at all. だんだん would be gradually, the opposite."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-iikae-0005', 'N2', 'iikae', null, 0, '＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。', 'その案は<u>あっさり</u>却下された。', 'あっさり', '["簡単に", "ようやく", "しぶしぶ", "全員に"]'::jsonb, 0, '["苦労の含みが逆", "気持ちの話であって難易度でない", "人数は問われていない"]'::jsonb, '{"es": "あっさり = sin más, sin resistencia. ようやく implicaría que costó, justo lo contrario.", "en": "あっさり = just like that, without resistance. ようやく would imply it took effort — the opposite."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-youhou-0001', 'N2', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '思いつく', '思いつく', '["シャワーを浴びているとき、いいアイデアを思いついた。", "昔のことを思いついて、懐かしくなった。", "彼の気持ちを思いついて、何も言えなかった。", "明日の予定を思いついておいてください。"]'::jsonb, 0, '["2は思い出す", "3は思いやる", "4は考えておく"]'::jsonb, '{"es": "思いつく = que se te ocurra algo de golpe. Recordar es 思い出す y ponerse en el lugar del otro es 思いやる.", "en": "思いつく = for an idea to strike you. Remembering is 思い出す and empathising is 思いやる."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-youhou-0002', 'N2', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '引き受ける', '引き受ける', '["駅で友達を引き受けた。", "難しい仕事だったが、引き受けることにした。", "重い荷物を引き受けて運んだ。", "彼の意見を引き受けて計画を変えた。"]'::jsonb, 1, '["1は迎える", "3は引き取る/運ぶ", "4は受け入れる"]'::jsonb, '{"es": "引き受ける = hacerse cargo de una tarea o responsabilidad. No se «hace cargo» de personas ni de opiniones.", "en": "引き受ける = to take on a task or responsibility. You don''t ''take on'' people or opinions."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-youhou-0003', 'N2', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', 'そそっかしい', 'そそっかしい', '["彼女はそそっかしい性格で、誰にでも優しい。", "この部屋はそそっかしくて落ち着かない。", "彼はそそっかしくて、よく忘れ物をする。", "そそっかしい味の料理は苦手だ。"]'::jsonb, 2, '["3は内容が矛盾", "2は騒がしい", "4は共起不可能"]'::jsonb, '{"es": "そそっかしい = atolondrado, descuidado. Sólo se dice de personas, y no cuadra con «amable con todos».", "en": "そそっかしい = scatterbrained. It only describes people, and doesn''t square with ''kind to everyone''."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-youhou-0004', 'N2', 'youhou', null, 0, '次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。', '相次ぐ', '相次ぐ', '["相次ぐ道をまっすぐ歩いた。", "彼女は質問に相次いで返事をした。", "昨日は彼と相次いで食事をした。", "今月に入って事故が相次いで起きている。"]'::jsonb, 3, '["3は共起不可能", "4はすぐに", "2は一緒に"]'::jsonb, '{"es": "相次ぐ = sucederse uno tras otro. Necesita varios sucesos del mismo tipo, no dos personas ni un camino.", "en": "相次ぐ = to happen one after another. It needs several events of the same kind, not two people or a road."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n3-bunpou1-0001', 'N3', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '雨が降っている（　）、試合は予定どおり行われた。', null, '["にもかかわらず", "によって", "にとって", "にたいして"]'::jsonb, 0, '["によっては手段や原因", "にとっては立場", "にたいしては対象"]'::jsonb, '{"es": "Llueve y aun así se juega: es concesivo, にもかかわらず. Los otros tres no marcan contraste.", "en": "It rains and the match happens anyway: concessive, にもかかわらず. The other three don''t mark contrast."}'::jsonb, null, null, null, null, '["逆接"]'::jsonb, 3),
  ('n3-bunpou1-0002', 'N3', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '先生に相談した（　）、気持ちが楽になった。', null, '["ばかりに", "おかげで", "せいで", "ために"]'::jsonb, 1, '["ばかりにも悪い結果", "せいでは悪い結果", "ためには中立だが感謝が出ない"]'::jsonb, '{"es": "El resultado es bueno, así que おかげで. せいで y ばかりに marcan una consecuencia mala.", "en": "The outcome is good, so おかげで. せいで and ばかりに mark a bad consequence."}'::jsonb, null, null, null, null, '["原因"]'::jsonb, 2),
  ('n3-bunpou1-0003', 'N3', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この機械は子どもでも使える（　）、操作がとても簡単だ。', null, '["わけで", "ために", "ように", "ところ"]'::jsonb, 2, '["わけでは結論", "ためには目的だが後件と合わない", "ところは場面"]'::jsonb, '{"es": "〜ように expresa el propósito: está hecho para que hasta un niño pueda usarlo.", "en": "〜ように expresses purpose: it''s built so that even a child can use it."}'::jsonb, null, null, null, null, '["目的"]'::jsonb, 2),
