  ('n5-bunshou_bunpou-0005', 'N5', 'bunshou_bunpou', 'n5-bb-g002', 0, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　1　）', null, '["でも", "だから", "たとえば", "それに"]'::jsonb, 0, '["前と後ろが反対なので理由にならない", "例ではない", "話を足しているのではない"]'::jsonb, '{"es": "El profesor se entiende, pero el japonés rápido no: son cosas opuestas, va でも.", "en": "The teacher is easy to follow, but fast Japanese isn''t — opposites, so でも."}'::jsonb, null, '{"texto": "わたしは 先月、日本語の きょうしつに 入りました。学校は 駅の 前に あって、うちから 二十分ぐらいです。クラスには いろいろな 国の 人が います。\n先生は ゆっくり 話しますから、よく わかります。（　1　）、まだ 早い 日本語は むずかしいです。毎日 少しずつ れんしゅうして います。\n先週、クラスの みんなで こうえんへ 行きました。おべんとうを 食べたり、しゃしんを （　2　） しました。とても 楽しかったです。\n来月、テストが あります。合かくしたいですから、今週から まいばん （　3　）と 思って います。\nいつか 日本の 友だちと 日本語だけで （　4　）なりたいです。", "notas": [{"termino": "合かく", "glosa": "テストに とおること"}]}'::jsonb, null, null, '["文章の文法"]'::jsonb, 2),
  ('n5-bunshou_bunpou-0006', 'N5', 'bunshou_bunpou', 'n5-bb-g002', 1, '次の文章を読んで、文章全体の内容を考えて、（　）に入る最もよいものを、1・2・3・4から一つ選びなさい。', '（　2　）', null, '["とったり", "とって", "とる", "とった"]'::jsonb, 0, '["〜たり〜たりの形になっていない", "〜たり〜たりの形になっていない", "〜たり〜たりの形になっていない"]'::jsonb, '{"es": "La frase ya lleva 食べたり, así que el segundo verbo también va en 〜たり.", "en": "The sentence already has 食べたり, so the second verb also takes 〜たり."}'::jsonb, null, null, null, null, '["文章の文法"]'::jsonb, 2),
