  ('n5-bunpou1-0001', 'N5', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'わたしは まいにち 学校（　）行きます。', null, '["へ", "を", "が", "ね"]'::jsonb, 0, '["を は目的語", "が は主語", "ね は文末"]'::jsonb, '{"es": "へ marca la dirección: 学校へ行く. を marcaría el complemento directo.", "en": "へ marks direction: 学校へ行く. を would mark a direct object."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunpou1-0002', 'N5', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'ペン（　）名前を 書きます。', null, '["に", "で", "も", "を"]'::jsonb, 1, '["に は場所や時間", "も は「〜も」", "を は目的語"]'::jsonb, '{"es": "で marca el medio o instrumento: con qué se hace algo.", "en": "で marks the means or instrument: what you do something with."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunpou1-0003', 'N5', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'へやに だれ（　）いません。', null, '["が", "か", "も", "は"]'::jsonb, 2, '["が は主語", "か は疑問", "は は主題"]'::jsonb, '{"es": "だれも＋negativo = «nadie». Con か sería «alguien», que pide frase afirmativa.", "en": "だれも + negative = ''nobody''. With か it would be ''somebody'', which needs an affirmative."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunpou1-0004', 'N5', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'あついです（　）、まどを あけましょう。', null, '["より", "だけ", "まで", "から"]'::jsonb, 3, '["より は比較", "だけ は限定", "まで は終点"]'::jsonb, '{"es": "から da la razón: «como hace calor, abramos la ventana».", "en": "から gives the reason: ''since it''s hot, let''s open the window.''"}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
