  ('n5-hyouki-0006', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'きょうは <u>あめ</u>が ふって います。', null, '["雨", "雪", "電", "雲"]'::jsonb, 0, '["ゆきと読む字", "でんと読む字", "くもと読む字"]'::jsonb, '{"es": "雨 (lluvia). 雪 es «nieve» y 雲 «nube».", "en": "雨 (rain). 雪 is snow and 雲 is cloud."}'::jsonb, null, null, null, null, '[]'::jsonb, 2),
  ('n5-hyouki-0007', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '<u>みず</u>を のみたいです。', null, '["水", "氷", "永", "木"]'::jsonb, 0, '["こおりと読む字", "形が似ているだけ", "きと読む字"]'::jsonb, '{"es": "水 (agua). 氷 es «hielo» y 木 «árbol»: se parecen pero no son.", "en": "水 (water). 氷 is ice and 木 is tree — similar shapes, different words."}'::jsonb, null, null, null, null, '[]'::jsonb, 2),
